/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 20.01.25
/// </summary>
class NDXUmsatzClass extends RunBase
{
    //#NDX_Thread
    //#NDX_Umsatz

    NDXKumUmsCust                   kumUmsCust;
    NDXKumUmsCustArtGrp             kumUmsCustArtGrp;
    NDXUmsCustArtGrp                nDXUmsCustArtGrp;
    NDXTmpCustomerAlliance          nDXTmpCustomerAlliance;
    NDXUmsatzBuilds                 nDXUmsatzBuilds;

    AccountNum                      accountNum;
    AccountNum                      masterAlliance;
    AccountNum                      accountNumCalculated;
    AccountNum                      CSCheckedForaccount;
    TreeItemIdx                     accountNumIdx;
    Array                           aUmsLfdJ, aUmsVJ;
    NDXJahr                         yearlfdJ, yearVJ;
    int                             nAnzChilds;
    boolean                         lInfoLog;
    FormStaticTextControl           ctrlStatus;
    NDXVerbandSE                    nDXVerband;
    NDXUmsatzAbschluss              nDXUmsatzAbschluss;
    NDXCompanyBE                    firma;
    CompanyId                       firmaAsCompanyId;
    Map                             mapFirma4Umsatz;

    FormRun                         dialogForm;
    Args                            argsCaller;
    boolean                         lTestEnvironment;
    boolean                         lInit1;
    boolean                         lBasisUmsLfdJ;
    boolean                         lCSIncl;                // Zentrallagerdaten darstellen
    boolean                         lSalesGroup;            // SalesDistrict oder SalesGroup
    container                       conFirmen;
    container                       conCompanies;
    container                       conUKs4Umsatz;          // UK's mit Umsatz
    NDXMonthYearSignature           monthYearSignature;
    NDXUmsSignature                 umsSignatureBase;
    NDXUmsSignature                 umsSignature;
    SysOperationProgressEmbedded    progressParent;
    boolean                         lThread;
    boolean                         lWithProt;
    boolean                         lGetDataOnly;           // nur Datensammlung (keine Aufbereitung für Formdarstellung)
    boolean                         lUseCalculatedData;     // bereits per Batch ermittelte Daten verwenden?
    boolean                         lGetDataPerChild;       // Umsatzdaten pro Verbandsmitglied (statt je Verband)
//    NDX_Umsatz2Excel                nDX_Umsatz2Excel;       // Datenaufbereitung für EXCEL
    boolean                         lAlliance;              // Auswertung über Verbandstruktur oder Verkaufsbereich
    smmSalesDistrictId              salesDistrictId;        // Verkaufsbereich
    CommissSalesGroup               salesGroupId;           // Verkaufsbereich (Provision)
    boolean                         lHasRLSCustTable;       // bestehen Einschränkungen auf der CustTable
    boolean                         lShowBonusDirectly;     // Sofortbonus extra darstellen?
    boolean                         lBonusDirectlyIncl;     // Sofortbonus dem Umsatz hinzuaddieren
    CurrencySymbol                  currencySymbol;         // Währungskennzeichen
    Version                         dataVersion;            // Daten versioniert aufbauen
    RefRecId                        dirPartyIdCalculated;   // kalkulierte DirPartyId
    int                             oldColorBG, oldColorFG; // Farbumsetzung bei Message-Anzeige

    Query                           qNDX_TmpKumUmsCustArtGrp;
    Query                           qNDX_TmpKumUmsCust;
    Query                           qNDX_KumUmsCustMonat;
    container                       conMessageCntrl;
    NDXUmsatzClassArgs              umsatzClassArgs;
    NDXSignature                    signatureArtGrp;
    NDXSignature                    signatureCust;
    NDXSignature                    signatureCS;
    NDXBatchWithMultithreading batchWithMultiThreading;
    RecId recIdNDXBatchProcessingTable;

    #define.CurrentVersion(2)
    #localmacro.CurrentList
        accountNum,
        lBasisUmsLfdJ,
        lCSIncl,
        firma,
        lAlliance,
        salesDistrictId,
        salesGroupId,
        lShowBonusDirectly,
        lBonusDirectlyIncl
    #endmacro

}

