/// <summary>
/// PaffH 16.01.25
/// </summary>
/// <param name = "_batchWithMultiThreading">NDXBatchWithMultithreading</param>
/// <returns>batchWithMultiThreading</returns>
NDXBatchWithMultithreading parmBatchWithMultiThreading(NDXBatchWithMultithreading _batchWithMultiThreading = batchWithMultiThreading)
{
    batchWithMultiThreading = _batchWithMultiThreading;
    return batchWithMultiThreading;
}

/// <summary>
/// DebuC 16.02.24
/// </summary>
/// <returns>boolean</returns>
protected boolean canRunInNewSession()
{
    boolean ret;

    ret = super();

    return ret;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_conFirmen">container</param>
/// <returns>container</returns>
container parmConFirmen(container _conFirmen = conFirmen)
{
    conFirmen = _conFirmen;
    return conFirmen;
}

    /// <summary>
    /// DebuC 22.09.23
    /// last modified: PaffH 16.01.25
    /// </summary>
    /// <param name = "args">NDXUmsatzClassArgs</param>
    protected void new(NDXUmsatzClassArgs args = null)
    {
        //NDX_ADSRunBaseBatch2    ndx_RunBaseBatch;
        ;
        super();

        yearlfdJ            = year(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
        yearVJ              = yearlfdJ - 1;
        dataVersion         = 0;
        lThread             = false;
        lWithProt           = false;
        aUmsLfdJ            = new Array(Types::Class);
        aUmsVJ              = new Array(Types::Class);
        mapFirma4Umsatz     = new Map(Types::Enum, Types::Integer);
        monthYearSignature  = this.parmMonthYearSignature(true);   // JahrMonat
        umsSignatureBase    = this.parmUmsSignatureBase('', true);
        umsSignature        = this.parmUmsSignature(umsSignature, true);
//        lHasRLSCustTable    = NDX_RLS::isRLSActive(tablenum(CustTable));
        conMessageCntrl     = connull();
        batchWithMultiThreading = NoYes::No;

        this.initVerband();

        currencySymbol      = Currency::NDXfindByCompanyInfo().Symbol;

        nDXUmsatzAbschluss = NDXUmsatzAbschluss::construct();

        if (args && args.parmlGetLastValues() != NDXNoYesBE::No)
        {
            xSysLastValue::getLast(this);
        }
        if (args && args.parmFirma())
        {
            firma = args.parmFirma();
        }

        this.parmlBasisUmsLfdJ(lBasisUmsLfdJ);  // Laufendes Jahr und Vorjahr setzen

        if (args && args.parmlCSIncl() != NDXNoYesBE::WithoutAssignment)
        {
            this.parmLCSIncl(args.parmlCSIncl() == NDXNoYesBE::Yes);
        }


        lGetDataOnly    = false;

        if (args)
        {
            argsCaller  = args;
            //ndx_RunBaseBatch = args.object();
            //if (ndx_RunBaseBatch)
            //    lTestEnvironment = ndx_RunBaseBatch.parmlTestImport();

        }

        if (args && (args.parmMaster() || args.parmSalesGroupId()))
        {
            if (args.parmLAlliance() != NDXNoYesBE::WithoutAssignment)
            {
                this.parmlAlliance(args.parmLAlliance() == NDXNoYesBE::Yes ? true : false);
            }
            if (args.parmMaster())
            {
                this.parmAccountNum(args.parmMaster());
                this.initVerband(args.parmMaster());
            }
            if (args.parmSalesGroupId())
            {
                this.parmSalesGroupId(args.parmSalesGroupId());
            }
        }

        // Einstellung für Umsatzbasis
        if (args)
        {
            switch (args.parmlBasisUmsLfdJ())
            {
                case NDXNoYesBE::Yes       :
                    this.parmlBasisUmsLfdJ(NoYes::Yes);
                    break;
                case NDXNoYesBE::No        :
                    this.parmlBasisUmsLfdJ(NoYes::No);
                    break;
            }
        }


    }

/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 20.01.25
/// </summary>
/// <param name = "args">NDXUmsatzClassArgs</param>
/// <returns>NDXUmsatzClass</returns>
static NDXUmsatzClass construct(NDXUmsatzClassArgs args = null)
{
    NDXUmsatzClass          nDXUmsatzClass;
    NDXGetUmsType           umsType = NDXGetUmsType::WithoutDefiniton;

    boolean                 lAlliance;
    CustAccount             master;
    CommissSalesGroup       salesGroupId;
    ;

    if (args &&
        args.parmEnumType() == enumnum(NDXGetUmsType))
    {
        umsType         = args.parmEnum();
    }
    nDXUmsatzClass =  new NDXUmsatzClass(args);

    if (args)
    {
        nDXUmsatzClass.parmBatchWithMultiThreading(args.parmBatchWithMultithreading());
        if (args.parmLAlliance() == NDXNoYesBE::WithoutAssignment)
        {
            lAlliance       = nDXUmsatzClass.parmlAlliance();
        }
        else
        {
            lAlliance       = args.parmLAlliance() == NDXNoYesBE::Yes ? true : false;
        }

        if (args.parmMaster())
        {
            master          = args.parmMaster();
        }
        else
        {
            master          = nDXUmsatzClass.parmAccountNum();
        }
        if (args.parmSalesGroupId())
        {
            salesGroupId    = args.parmSalesGroupId();
        }
        else
        {
            salesGroupId    = nDXUmsatzClass.parmSalesGroupId();
        }

        nDXUmsatzClass.parmDataVersion(args.parmDataVersion());
        if (args.parmDataVersion() == NDXUmsatzConstants::DataVersionVerband ||
            args.parmDataVersion() == NDXUmsatzConstants::DataVersionVKBereich)
        {
            nDXUmsatzClass.parmMonthYearSignature(true, nDXUmsatzClass.monthYearSignatureBase(), false);
        }

        if (args.parmlCSIncl() != NDXNoYesBE::WithoutAssignment)
        {
            nDXUmsatzClass.parmLCSIncl(args.parmlCSIncl() == NDXNoYesBE::Yes);
        }
        if (args.parmlShowBonusDirectly() != NDXNoYesBE::WithoutAssignment)
        {
            nDXUmsatzClass.parmLShowBonusDirectly(args.parmlShowBonusDirectly() == NDXNoYesBE::Yes);
        }
        if (args.parmlBonusDirectlyIncl() != NDXNoYesBE::WithoutAssignment)
        {
            nDXUmsatzClass.parmLBonusDirectlyIncl(args.parmlBonusDirectlyIncl() == NDXNoYesBE::Yes);
        }
    }

    // Auszuwertende Firmen
    nDXUmsatzClass.initFirmen();

    // GetDataOnly
    switch (umsType)
    {
        case NDXGetUmsType::perCustomerThread      :
        case NDXGetUmsType::perAlliance            :
        case NDXGetUmsType::perAllianceThread      :
        case NDXGetUmsType::Init4AllianceRun       :
        case NDXGetUmsType::Init4AllianceRunOne    :
        case NDXGetUmsType::Init4SalesGroupRun     :
            nDXUmsatzClass.parmLGetDataOnly(true);
            break;
    }


    // Umsatzsignatur
    switch (umsType)
    {
        case NDXGetUmsType::perCustomerThread  :
            nDXUmsatzClass.parmUmsSignature(strfmt('%1%2', curuserid(), NDXUmsatzConstants::Thread));
            break;
        case NDXGetUmsType::perAlliance            :
        case NDXGetUmsType::perAllianceThread      :
        case NDXGetUmsType::Init4AllianceRun       :
        case NDXGetUmsType::Init4AllianceRunOne    :
        case NDXGetUmsType::Init4SalesGroupRun     :
            nDXUmsatzClass.parmUmsSignature(nDXUmsatzClass.getCalculatedUser());
            break;
    }

    // Threadsteuerung ?
    switch (umsType)
    {
        //case NDX_GetUmsType::ohneFestlegung     :
        //if (box::yesNo("@NXD1271", DialogButton::No)==DialogButton::Yes)        // Soll die Datenermittlung über Threads erfolgen?
        //    nDX_UmsatzClass.parmLThread(true);
        case NDXGetUmsType::perCustomerThread      :
        case NDXGetUmsType::perAllianceThread      :
            nDXUmsatzClass.parmLThread(true);
            break;
    }

    // Tabelleninitialisierung (Alliance)
    switch (umsType)
    {
        case NDXGetUmsType::perAllianceThread      :
        case NDXGetUmsType::Init4AllianceRun       :
            nDXUmsatzClass.initTables4Alliance();
            break;
    }

    // Tabelleninitialisierung (ThreadRun)
    switch (umsType)
    {
        case NDXGetUmsType::perCustomerThread      :
        case NDXGetUmsType::Init4ThreadRun         :
        case NDXGetUmsType::Init4AllianceRun       :
        case NDXGetUmsType::Init4AllianceRunOne    :
            nDXUmsatzClass.init4ThreadRun();
            break;
    }
    // Tabelleninitialisierung (Allgemein)
    switch (umsType)
    {
        case NDXGetUmsType::perCustomer            :
        case NDXGetUmsType::perCustomerThread      :
        case NDXGetUmsType::Init4ThreadRun         :
        case NDXGetUmsType::Init4AllianceRun       :
        case NDXGetUmsType::Init4AllianceRunOne    :
        case NDXGetUmsType::Init4SalesGroupRun     :
            nDXUmsatzClass.initTables();
            nDXUmsatzClass.initNDXKumUmsCustMonat();
            break;
    }

    // Verband initialisieren
    nDXUmsatzClass.initVerband();

    return nDXUmsatzClass;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "lSet">boolean</param>
/// <param name = "l_monthYearSignature">NDXMonthYearSignature</param>
/// <param name = "lCheckUseCompressedData">boolean</param>
/// <returns>NDXMonthYearSignature</returns>
public NDXMonthYearSignature parmMonthYearSignature(boolean                    lSet = false,
                                                 NDXMonthYearSignature     l_monthYearSignature = monthYearSignature,
                                                 boolean                    lCheckUseCompressedData = true)
{
    NDXTmpKumUmsCust        nDXTmpKumUmsCust;
    ;
    if (lSet)
    {
        monthYearSignature  = this.monthYearSignatureBase();

        if (lCheckUseCompressedData)
        {
            // Falls mit dieser Signatur keine verdichteten Daten aufbereitet wurden
            // kann die letzte Verdichtung genutzt werden
            select firstOnly   monthYearSignature
                from       nDXTmpKumUmsCust
                where      nDXTmpKumUmsCust.umsSignature       == NDXUmsatzConstants::CalculatedUser
                    &&     nDXTmpKumUmsCust.monthYearSignature == monthYearSignature;

            if (!nDXTmpKumUmsCust)
            {
                if (NDXUmsatzParametersGlobal::getUseCompressedData() == NoYes::Yes)
                {
                    select firstOnly    monthYearSignature
                    from            nDXTmpKumUmsCust
                    group by        monthYearSignature desc
                        where           nDXTmpKumUmsCust.umsSignature == NDXUmsatzConstants::CalculatedUser &&
                                    nDXTmpKumUmsCust.monthYearSignature <= monthYearSignature;

                    if (nDXTmpKumUmsCust)
                    {
                        monthYearSignature = NDXTmpKumUmsCust.MonthYearSignature;
                    }
                }
            }
        }
    }
    //--> 1.2: NDX/PaffH/29.03.2011
    if (!prmisdefault(l_monthYearSignature) && l_monthYearSignature)
    {
        monthYearSignature = l_monthYearSignature;
    }
    //<-- NDX/PaffH/29.03.2011

    return monthYearSignature;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_umsSignatureBase">NDXUmsSignature</param>
/// <param name = "lSet">boolean</param>
/// <returns>NDXUmsSignature</returns>
public NDXUmsSignature parmUmsSignatureBase(NDXUmsSignature _umsSignatureBase = umsSignatureBase, boolean lSet = false)
{
    umsSignatureBase = _umsSignatureBase;
    if (lSet)
    {
        umsSignatureBase = curuserid();
    }

    return umsSignatureBase;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <returns>NDXMonthYearSignature</returns>
public NDXMonthYearSignature monthYearSignatureBase()
{
    str                     sDate;
    NDXMonthYearSignature   lMonthYearSignature;
    ;
    sDate                   = date2str(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()), 321, DateDay::Digits2, DateSeparator::None, DateMonth::Digits2, DateSeparator::None, DateYear::Digits4);
    lMonthYearSignature      = substr(sDate, 1, 6);   // JahrMonat

    if (!this.parmlBasisUmsLfdJ())
    {
        lMonthYearSignature = strfmt('%1%2', yearlfdJ, substr(lMonthYearSignature, 5,2)); // lfd.J entspricht bereits dem Vorjahr!
    }

    return lMonthYearSignature;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_lBasisUmsLfdJ">NoYes</param>
/// <returns>NoYes</returns>
public NoYes   parmlBasisUmsLfdJ(NoYes _lBasisUmsLfdJ = lBasisUmsLfdJ)
{
    ;

    if (!prmisdefault(_lBasisUmsLfdJ))
    {
        lBasisUmsLfdJ = _lBasisUmsLfdJ;
        if (lBasisUmsLfdJ == NoYes::Yes)
        {
            this.parmYearlfdJ(year(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
        }
        else
        {
            this.parmYearlfdJ(year(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-1);
        }
        this.parmMonthYearSignature(true);                                     // 1.1: NDX/PaffH/24.03.2011

        //xSysLastValue::saveLast(this);

        // Basis wurde verändert; also bisherige kum. Umsatzwerte verwerfen
        if (this.parmlUseCalculatedData())
        {
            this.initTmpKumUmsCust(false, true);
        }
        else
        {
            this.initTmpKumUmsCust();
        }
    }

    return lBasisUmsLfdJ;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_yearlfdJ">NDXYear</param>
/// <returns>NDXYear</returns>
public NDXYear parmYearlfdJ(NDXYear _yearlfdJ = yearlfdJ)
{
    yearlfdJ = _yearlfdJ;
    yearVJ   = yearlfdJ - 1;

    return yearlfdJ;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_lUseCalculatedData">boolean</param>
/// <returns>boolean</returns>
boolean parmlUseCalculatedData(boolean _lUseCalculatedData = lUseCalculatedData)
{
    ;
    lUseCalculatedData  = _lUseCalculatedData;
    return lUseCalculatedData;
}

/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 29.03.25
/// </summary>
/// <param name = "lInitSignature">boolean</param>
/// <param name = "lInit4CalculatedData">boolean</param>
void initTmpKumUmsCust(boolean lInitSignature = false, boolean lInit4CalculatedData = false)
{
    NDXTmpKumUmsCust            nDXTmpKumUmsCust;
    NDXTmpKumUmsCustArtGrp      nDXTmpKumUmsCustArtGrp;
    NDXTmpCSAllianceArtGrp     nDXTmpCSAllianceArtGrp;
    NDXTmpCustomerAlliance      lnDXTmpCustomerAlliance;
    NDXTmpCSAlliance            nDXTmpCSAlliance;
    int                         i;
    dataAreaId                  company;
    boolean                     lAllianceValues;
    accountNum                  l_Alliance;
    NDXUmsSignature             lUmsSignature;
    Query                       q;
    QueryRun                    qr;
    QueryBuildDataSource        qbds;
    str infoAddition;

    lAllianceValues = NDXUmsatzClass::AllianceOrSalesGroupValues(this.parmlAlliance(), this.parmlUseCalculatedData(), this.parmLGetDataOnly(), this.parmNDXVerband().parmlSalesGroupMaster());
    lUmsSignature  = lInit4CalculatedData ? this.getCalculatedUser() : umsSignature;

    for (i = 1; i <= conlen(conCompanies); i++)
    {
        company = conpeek(conCompanies, i);
        changecompany(company)
        {
            nDXTmpKumUmsCust           = null;
            nDXTmpKumUmsCustArtGrp     = null;
            lnDXTmpCustomerAlliance    = null;
            nDXTmpCSAlliance           = null;
            nDXTmpCSAllianceArtGrp    = null;

            if (!lAllianceValues && this.parmSalesGroupId())
            {
                l_Alliance  = this.parmSalesGroupId();
            }
            else
            {
                l_Alliance  = this.parmAccountNum();
            }

            if (l_Alliance && !lInitSignature)
            {
                // NDX_TmpKumUmsCust
                if (!lInit4CalculatedData)
                {
                    q       = new Query();
                    qbds    = q.addDataSource(tablenum(NDXTmpKumUmsCust));
                    qbds.update(true);
                    qbds.addRange(fieldnum(NDXTmpKumUmsCust, umsSignature)).value(lUmsSignature);
                    qbds.addRange(fieldnum(NDXTmpKumUmsCust, MonthYearSignature)).value(monthYearSignature);
                    if (l_Alliance != NDXUmsatzConstants::all)
                    {
                        if (this.parmPartyIdCalculated())
                        {
                            qbds.addRange(fieldnum(NDXTmpKumUmsCust, Party)).value(queryValue(this.parmPartyIdCalculated()));
                        }
                        else
                        {
                            qbds.addRange(fieldnum(NDXTmpKumUmsCust, Alliance)).value(l_Alliance);
                        }
                    }
                    qr = new QueryRun(q);
                    ttsbegin;
                    while (qr.next())
                    {
                        nDXTmpKumUmsCust = qr.get(tablenum(NDXTmpKumUmsCust));
                        nDXTmpKumUmsCust.delete();
                    }
                    ttscommit;
                }

                // NDX_TmpKumUmsCustArtGrp
                if (!lInit4CalculatedData)
                {
                    q       = new Query();
                    qbds    = q.addDataSource(tablenum(NDXTmpKumUmsCustArtGrp));
                    qbds.update(true);
                    qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, umsSignature)).value(lUmsSignature);
                    qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, MonthYearSignature)).value(monthYearSignature);
                    if (lAllianceValues && this.parmAccountNum())
                    {
                        if (this.parmPartyIdCalculated())
                        {
                            qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, Party)).value(queryValue(this.parmPartyIdCalculated()));
                        }
                        else
                        {
                            qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, Alliance)).value(this.parmAccountNum());
                        }
                    }
                    if (!lAllianceValues && this.parmSalesGroupId())
                    {
                        if (this.parmSalesGroupId() != NDXUmsatzConstants::all) 
                        {
                            qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, SalesGroup)).value(this.parmSalesGroupId());
                        }
                    }
                    qr = new QueryRun(q);
                    try
                    {
                        ttsbegin;
                        while (qr.next())
                        {
                            nDXTmpKumUmsCustArtGrp = qr.get(tablenum(NDXTmpKumUmsCustArtGrp));
                            nDXTmpKumUmsCustArtGrp.delete();
                        }
                        ttscommit;
                    }
                    catch (Exception::Deadlock)
                    {
                        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
                        {
                            infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), nDXTmpKumUmsCustArtGrp.Alliance, nDXTmpKumUmsCustArtGrp.Child, nDXTmpKumUmsCustArtGrp.ItemGroup, nDXTmpKumUmsCustArtGrp.UmsSignature, nDXTmpKumUmsCustArtGrp.MonthYearSignature);
                            infoAddition += " NDXUmsatzClass:645";
                            throw Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(nDXTmpKumUmsCustArtGrp.TableId)) + infoAddition);
                        }
                        else
                        {
                            sleep(NDXExceptionConstants::RetryInterval500);
                            retry;
                        }
                    }
                    catch (Exception::UpdateConflict)
                    {
                        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
                        {
                            infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), nDXTmpKumUmsCustArtGrp.Alliance, nDXTmpKumUmsCustArtGrp.Child, nDXTmpKumUmsCustArtGrp.ItemGroup, nDXTmpKumUmsCustArtGrp.UmsSignature, nDXTmpKumUmsCustArtGrp.MonthYearSignature);
                            infoAddition += " NDXUmsatzClass:656";
                            throw Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(nDXTmpKumUmsCustArtGrp.TableId)) + infoAddition);
                        }
                        else
                        {
                            sleep(NDXExceptionConstants::RetryInterval500);
                            retry;
                        }
                    }
                }

                // NDXTmpCustomerAlliance
                q       = new Query();
                qbds    = q.addDataSource(tablenum(NDXTmpCustomerAlliance));
                qbds.update(true);
                qbds.addRange(fieldnum(NDXTmpCustomerAlliance, UmsSignature)).value(lUmsSignature);
                if (l_Alliance != NDXUmsatzConstants::all)
                {
                    qbds.addRange(fieldnum(NDXTmpCustomerAlliance, Alliance)).value(l_Alliance);
                }
                qr = new QueryRun(q);
                ttsbegin;
                while (qr.next())
                {
                    lnDXTmpCustomerAlliance = qr.get(tablenum(NDXTmpCustomerAlliance));
                    lnDXTmpCustomerAlliance.delete();
                }
                ttscommit;

                // NDXTmpCustomerAllianceBlock
                NDXTmpCustomerAllianceBlock lnDXTmpCustomerAllianceBlock;
                q       = new Query();
                qbds    = q.addDataSource(tablenum(NDXTmpCustomerAllianceBlock));
                qbds.update(true);
                qbds.addRange(fieldnum(NDXTmpCustomerAllianceBlock, UmsSignature)).value(lUmsSignature);
                if (l_Alliance != NDXUmsatzConstants::all)        
                {
                    qbds.addRange(fieldnum(NDXTmpCustomerAllianceBlock, Alliance)).value(l_Alliance);
                }
                qr = new QueryRun(q);
                ttsbegin;
                while (qr.next())
                {
                    lnDXTmpCustomerAllianceBlock = qr.get(tablenum(NDXTmpCustomerAllianceBlock));
                    lnDXTmpCustomerAllianceBlock.delete();
                }
                ttscommit;

                // NDX_TmpCSAlliance
                if (!lInit4CalculatedData)
                {
                    q       = new Query();
                    qbds    = q.addDataSource(tablenum(NDXTmpCSAlliance));
                    qbds.update(true);
                    qbds.addRange(fieldnum(NDXTmpCSAlliance, umsSignature)).value(lUmsSignature);
                    qbds.addRange(fieldnum(NDXTmpCSAlliance, monthYearSignature)).value(monthYearSignature);
                    if (lAllianceValues && this.parmAccountNum())
                    {
                        qbds.addRange(fieldnum(NDXTmpCSAlliance, Alliance)).value(this.parmAccountNum());
                    }
                    qr = new QueryRun(q);
                    ttsbegin;
                    while (qr.next())
                    {
                        nDXTmpCSAlliance = qr.get(tablenum(NDXTmpCSAlliance));
                        nDXTmpCSAlliance.delete();
                    }
                    ttscommit;
                }

                // NDX_TmpCSAllianceArtGrp
                if (!lInit4CalculatedData)
                {
                    q       = new Query();
                    qbds    = q.addDataSource(tablenum(NDXTmpCSAllianceArtGrp));
                    qbds.update(true);
                    qbds.addRange(fieldnum(NDXTmpCSAllianceArtGrp, umsSignature)).value(lUmsSignature);
                    qbds.addRange(fieldnum(NDXTmpCSAllianceArtGrp, monthYearSignature)).value(monthYearSignature);
                    if (lAllianceValues && this.parmAccountNum())
                    {
                        qbds.addRange(fieldnum(NDXTmpCSAllianceArtGrp, Alliance)).value(this.parmAccountNum());
                    }
                    qr = new QueryRun(q);
                    ttsbegin;
                    while (qr.next())
                    {
                        nDXTmpCSAllianceArtGrp = qr.get(tablenum(NDXTmpCSAllianceArtGrp));
                        nDXTmpCSAllianceArtGrp.delete();
                    }
                    ttscommit;
                }

            }
            else
            {
                try
                {
                    if (!lInit4CalculatedData)
                    {
                        delete_from nDXTmpKumUmsCust
                        where   nDXTmpKumUmsCust.UmsSignature                  == lUmsSignature &&
                                nDXTmpKumUmsCust.MonthYearSignature            == monthYearSignature;
                    }

                    if (!lInit4CalculatedData)
                    {
                        delete_from nDXTmpKumUmsCustArtGrp
                        where   nDXTmpKumUmsCustArtGrp.UmsSignature            == lUmsSignature &&
                                nDXTmpKumUmsCustArtGrp.MonthYearSignature      == monthYearSignature;
                    }

                    delete_from nDXTmpCustomerAlliance
                    where   nDXTmpCustomerAlliance.UmsSignature               == lUmsSignature;
                    //delete_from nDXTmpCustomerAllianceBlock
                    //    where   nDXTmpCustomerAllianceBlock.UmsSignature          == lUmsSignature;

                    if (!lInit4CalculatedData)
                    {
                        delete_from NDXTmpCSAlliance
                        where   NDXTmpCSAlliance.UmsSignature                  == lUmsSignature   &&
                                nDXTmpCSAlliance.MonthYearSignature            == monthYearSignature;
                    }

                    if (!lInit4CalculatedData)
                    {
                        delete_from nDXTmpCSAllianceArtGrp
                        where   nDXTmpCSAllianceArtGrp.UmsSignature           == lUmsSignature   &&
                                nDXTmpCSAllianceArtGrp.MonthYearSignature     == monthYearSignature;
                    }
                }
                catch (Exception::Deadlock)
                {
                    if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
                    {
                        infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), nDXTmpKumUmsCustArtGrp.Alliance, nDXTmpKumUmsCustArtGrp.Child, nDXTmpKumUmsCustArtGrp.ItemGroup, nDXTmpKumUmsCustArtGrp.UmsSignature, nDXTmpKumUmsCustArtGrp.MonthYearSignature);
                        infoAddition += " NDXUmsatzClass:794";
                        throw Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(nDXTmpKumUmsCustArtGrp.TableId)) + infoAddition);
                    }
                    else
                    {
                        sleep(NDXExceptionConstants::RetryInterval500);
                        retry;
                    }
                }
                catch (Exception::UpdateConflict)
                {
                    if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
                    {
                        infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), nDXTmpKumUmsCustArtGrp.Alliance, nDXTmpKumUmsCustArtGrp.Child, nDXTmpKumUmsCustArtGrp.ItemGroup, nDXTmpKumUmsCustArtGrp.UmsSignature, nDXTmpKumUmsCustArtGrp.MonthYearSignature);
                        infoAddition += " NDXUmsatzClass:808";
                        throw Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(nDXTmpKumUmsCustArtGrp.TableId)) + infoAddition);
                    }
                    else
                    {
                        sleep(NDXExceptionConstants::RetryInterval500);
                        retry;
                    }
                }
            }
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "l_lAlliance">boolean</param>
/// <param name = "lUseCalculatedData">boolean</param>
/// <param name = "lGetDataOnly">boolean</param>
/// <param name = "lSalesGroupMaster">boolean</param>
/// <returns>boolean</returns>
static boolean AllianceOrSalesGroupValues(boolean               l_lAlliance,
                                      boolean               lUseCalculatedData  = false,
                                      boolean               lGetDataOnly        = false,
                                      boolean               lSalesGroupMaster   = false)
{
    boolean lAlliance = l_lAlliance;
    lAlliance   = lAlliance || !lUseCalculatedData;

    if (!prmisdefault(lSalesGroupMaster) && lSalesGroupMaster)
    {
        lAlliance = false;
    }

    if (lGetDataOnly)
    {
        lAlliance   = l_lAlliance;
    }

    return lAlliance;
}

