/// <summary>
/// DebuC 22.09.23
/// </summary>
void initNDXKumUmsCustMonat()
{
    NDXKumUmsCustMonat     kumUmsCustMonat;
    RecordInsertList       insertList = new RecordInsertList(tableNum(NDXKumUmsCustMonat), true);

    int                     i, j;
    NDXCompanyBE            company;

    for (i=1; i <= conlen(conFirmen)+1; i++)
    {
        if (i > conlen(conFirmen))
        {
            company  = NDXCompanyBE::AllCompanies;
        }
        else
        {
            company  = conpeek(conFirmen, i);
        }

        delete_from kumUmsCustMonat
        where   kumUmsCustMonat.Company == company &&
                kumUmsCustMonat.UmsSignature == umsSignature;

        for (j=1; j <= NDXMonthBE::December; j++)
        {
            kumUmsCustMonat.clear();
            kumUmsCustMonat.Month = j;
            kumUmsCustMonat.Company = company;
            kumUmsCustMonat.UmsSignature = umsSignature;
            insertList.add(kumUmsCustMonat);
        }
    }
    insertList.insertDatabase();
}

