/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 20.01.25
/// </summary>
/// <param name = "l_args">NDXUmsatzClassArgs</param>
static server void FillCSStatistikData(NDXUmsatzClassArgs l_args)
{

    const str verkaufsbereich = 'Verkaufsbereich';
    const str verband = 'Verband';
    NDXMasterAlliance           nDX_MasterAlliance;
    CommissionSalesGroup        commissionSalesGroup;
    NDXUmsatzClassArgs         args = new NDXUmsatzClassArgs();

    int                         nStatus;
    List                        listThread = new List(Types::Class);
    System.Threading.Tasks.Task t;
    int                         nCounter;
    int                         nBis = 10;
    int                         nAnz, i;
    ListIterator                iterator;
    NDXGetUmsType               umsType;
    NDXUmsatzClass              nDXUmsatzClass;
    CompanyId                   company;

    Query                       q;
    QueryRun                    qr;
    QueryBuildDataSource        qbds;

    boolean                     lThread         = l_args.parmlThread();
    //boolean                     lBuildVerband   = l_args.parmlBuildVerband();
    CustAccount                 alliance        = l_args.parmMaster();
    CommissSalesGroup           salesGroup      = l_args.parmSalesGroupId();
    NDXNoYesBE                  lBasisUmsLfdJ   = l_args.parmlBasisUmsLfdJ();
    boolean                     lisBatch        = l_args.parmLisBatch();

    NDXJobMangerJobsClass       nDX_JobManagerJobs;
    str                         actionStr, actionID;
    container                   conCompanys;

    info(strfmt("@NDX:NDXDetermineCentralSalesVolume", NDXHelperCommon::seconds2Str(), salesGroup ? verkaufsbereich : verband));             // [%1] Start: Zentralumsätze ermitteln [%2]

    nDX_JobManagerJobs = NDXJobMangerJobsClass::construct(NDXJobManagerJobId::getUmsVerband_L1);
    //TODO: DebuC austauschen der Winapi durch Protokolltabelle
    nDX_JobManagerJobs.openFileToWrite();
    nDX_JobManagerJobs.start();

    if (!lisBatch)
    {
        //TODO DebuC: (PaffH 30.01.25) lBuildVerband wird nicht weiter ausgewertet; daher ausdokumentiert
        //lBuildVerband = (box::yesNo("@NDX:NDXRebuildMasterAlliance" /*Soll die MasterAlliance-Tabelle neu aufgebaut werden?*/, DialogButton::Yes, "@NDX:NDXPrepareCSEvaluationStatistic" /*Statistiken , die für die CS-Auswertung benötigt werden, aufbereiten*/) == DialogButton::Yes);
    }

    conCompanys = NDXUmsatzCompanies::CompanyId2con();
    info(strfmt("@NDX:NDXMasterAllianceDetermination", NDXHelperCommon::seconds2Str(), Con2Str(conCompanys)));                  // [%1] Ermittlung der MasterAlliance aus (%2)
    nAnz = NDXVerbandSE::getMasters(conCompanys);
    info(strfmt("@NDX:NDXMasterAllianceDetermined", NDXHelperCommon::seconds2Str(), nAnz));             // [%1] [%2] MasterAlliance ermittelt

    // Grundinitialisierung (z.B. temp. Tabellen)
    args.parmLAlliance(NDXNoYesBE::Yes);
    args.parmlGetLastValues(l_args.parmlGetLastValues());                           // lGetLastValues ?
    args.parmlBasisUmsLfdJ(l_args.parmlBasisUmsLfdJ());                             // Umsatzzahlen für aktuelles Jahr ermitteln?
    args.parmlCSIncl(l_args.parmlCSIncl());                                         // Zentrallagerverteilung einbeziehen
    args.parmBatchWithMultithreading(l_args.parmBatchWithMultithreading());
    if (!l_args.parmDataVersion())
    {
        args.parmDataVersion(1);
    }
    else
    {
        args.parmDataVersion(l_args.parmDataVersion());
    }

    if (salesGroup)
    {
        umsType = NDXGetUmsType::Init4SalesGroupRun;
        args.parmLAlliance(NDXNoYesBE::No);
        args.parmSalesGroupId(salesGroup);
    }
    else if (alliance)
    {
        umsType = NDXGetUmsType::Init4AllianceRunOne;
        args.parmMaster(alliance);
    }
    else
    {
        umsType = NDXGetUmsType::Init4AllianceRun;
    }
    args.parmEnumType(enumnum(NDXGetUmsType));
    args.parmEnum(enum2int(umsType));
    nDXUmsatzClass = NDXUmsatzClass::construct(args);

    nDXUmsatzClass.parmLThread(lThread);                                       
    // HP 19.01.11  über Thread funktionierts noch nicht
    nDXUmsatzClass.parmlAlliance(args.parmLAlliance() == NDXNoYesBE::Yes ? true : false);
    if (!nDXUmsatzClass.parmlAlliance())
    {
        nDXUmsatzClass.parmSalesGroupId(salesGroup);
        nDXUmsatzClass.parmNDXVerband().parmlSalesGroupMaster(l_args.parmlSalesGroupMaster());
    }

    nAnz    = 0;

    for (i=1; i<=conlen(conCompanys); i++)
    {
        company = conpeek(conCompanys, i);

        nDXUmsatzClass.initFirmen([NDXHelperCommon::CompanyId2NDXCompany(company)]);

        changecompany(company)
        {
            q       = new Query();
            if (nDXUmsatzClass.parmlAlliance())
            {
                qbds    = q.addDataSource(tablenum(NDXMasterAlliance));
                qbds.addRange(fieldnum(NDXMasterAlliance, Company)).value(company);
                qbds.addRange(fieldnum(NDXMasterAlliance, Type)).value(queryValue(NDXMasterAllianceType::TOSId)); // PaffH 23.01.25
                if (alliance)
                {
                    qbds.addRange(fieldnum(NDXMasterAlliance, AllianceMaster)).value(alliance);
                }
            }
            else
            {
                qbds    = q.addDataSource(tablenum(CommissionSalesGroup));
                if (salesGroup != NDXUmsatzConstants::all)
                {
                    qbds.addRange(fieldnum(CommissionSalesGroup, GroupId)).value(salesGroup);
                }
            }

            qr      = new QueryRun(q);
            while (qr.next())
            {
                ++nCounter;

                if (nDXUmsatzClass.parmlAlliance())
                {
                    nDX_MasterAlliance      = qr.get(tablenum(NDXMasterAlliance));
                    nDXUmsatzClass.parmAccountNum(nDX_MasterAlliance.AllianceMaster);
                    info(strfmt('[%1] %2.) Verband [%3-%4] %5', 
                        NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), 
                        nCounter, nDX_MasterAlliance.AllianceMaster, company, 
                        lBasisUmsLfdJ ==  NDXNoYesBE::Yes ? "@NDXBase:NDXCurrentYear" : "@NDXBase:NDXLastYear"));
                    actionID  = strfmt('%1-%2', company, nDX_MasterAlliance.AllianceMaster);
                    actionStr = strfmt('Verband [%1]', 
                        lBasisUmsLfdJ ==  NDXNoYesBE::Yes ? "@NDXBase:NDXCurrentYear" : "@NDXBase:NDXLastYear");       // "laufendes Jahr" : "Vorjahr"
                }
                else
                {
                    commissionSalesGroup    = qr.get(tablenum(CommissionSalesGroup));
                    nDXUmsatzClass.parmSalesGroupId(commissionSalesGroup.GroupId);
                    info(strfmt('[%1] %2.) Verkaufsbereich [%3-%4] %5', 
                        NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), 
                        nCounter, commissionSalesGroup.GroupId, company, 
                        lBasisUmsLfdJ == NDXNoYesBE::Yes ? "@NDXBase:NDXCurrentYear" : "@NDXBase:NDXLastYear"));
                    actionID  = strfmt('%1-%2', company, commissionSalesGroup.GroupId);
                    actionStr = strfmt('Verkaufsbereich [%1]', 
                        lBasisUmsLfdJ ==  NDXNoYesBE::Yes ? "@NDXBase:NDXCurrentYear" : "@NDXBase:NDXLastYear");       // "laufendes Jahr" : "Vorjahr"
                }

                nDX_JobManagerJobs.setAction(strfmt('UK [%1] %2', company, actionStr), actionID, nCounter);

                //lThread = true;
                if (lThread)
                {
                    // HP - Test: 10 überspringen
                    if (nCounter < 5)
                    {
                        continue;
                    }
                    if (nCounter >= nBis)
                    {
                        break;
                    }
                }
                //t = NDX_UmsatzClassThread::runGetUmsAlliance(nDX_MasterAlliance.AllianceMaster, nDX_UmsatzClass.parmLThread(), nDX_UmsatzClass);
                t = NDXUmsatzClassThread::runGetUmsAlliance(nDXUmsatzClass);
                ++nAnz;
                /*
                t = NDX_UmsatzClassThread::construct();
                t = NDX_UmsatzClassThread::getUmsAlliance(t, nDX_MasterAlliance.AllianceMaster, lThread);
                if (t.status() == NDX_ThreadStatus::ErrorInThread)
                    Warning(strfmt("Thread-Fehler bei Master [%1]", nDX_MasterAlliance.AllianceMaster));
                */
                if (lThread)
                {
                    listThread.addEnd(t);
                }

            }
        }
    }

    // Warten, bis alle Threads beendet sind
    while (!listThread.empty())
    {
        iterator = new ListIterator(listThread);
        while (iterator.more())
        {
            t = iterator.value();
            nStatus = t.Status;
            if (nStatus == System.Threading.Tasks.TaskStatus::RanToCompletion ||
                nStatus == System.Threading.Tasks.TaskStatus::Canceled ||
                nStatus == System.Threading.Tasks.TaskStatus::Faulted)
            {
                iterator.delete();
            }
            iterator.next();
        }
        sleep(1000);
    }

    info(strfmt("@NDX:NDXDetermineCentralSalesVolumeEnd", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), salesGroup ? verkaufsbereich : verband, nAnz));      // [%1] Ende: [%3] Zentralumsätze ermitteln [%2]

    if (salesGroup)
    {
        NDXUmsatzParametersGlobal::setLastBuildSalesGroup();
    }
    else
    {
        NDXUmsatzParametersGlobal::setLastBuildAlliance();
    }
    nDX_JobManagerJobs.ende();
}

/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 17.02.25
/// </summary>
/// <param name = "inputParm">Container</param>
static server void getUmsAlliance(Container inputParm)
{
    NDXTmpUmsatzClassThreadControl threadControl;
    NDXThreadControl               nDXThreadControl;

    NDXUmsatzClassArgs      args = new NDXUmsatzClassArgs();
    NDXGetUmsType           umsType;
    NDXUmsatzClass          nDXUmsatzClass;
    nDXVerbandSE              nDXVerband;
    NDXUmsSignature         umsSignature;
    CustAccount             alliance;
    int                     conPos;
    boolean                 lThread;
    int                     threadSession;
    int                     i;
    boolean                 lAlliance;
    CommissSalesGroup       salesGroupId;
    Version                 dataVersion;       
    boolean                 lBasisUmsLfdJahr;
    boolean                 lCSIncl;
    boolean                 lSalesGroupMaster;

    NDXJobMangerJobsClass   nDX_JobManagerJobs;
    str                     actionStr;
    container               conFirmen = connull();
    int                     conLen;
    NDXSignature            signatureValuesArtGrp;
    NDXSignature            signatureValuesCust;
    NDXSignature            signatureValuesCS;

    System.Threading.Tasks.Task  taskArtGrp;
    System.Threading.Tasks.Task  taskCust;
    System.Threading.Tasks.Task  taskCS;

    conPos                          = 0;
    ++conPos; 
    umsSignature          = conpeek(inputParm, conPos);
    ++conPos; 
    lThread               = conpeek(inputParm, conPos);

    // PaffH 13.02.25
    lThread = true;

    ++conPos; 
    lalliance             = conpeek(inputParm, conPos);
    ++conPos; 
    alliance              = conpeek(inputParm, conPos);
    ++conPos; 
    salesGroupId          = conpeek(inputParm, conPos);
    ++conPos; 
    dataVersion           = conpeek(inputParm, conPos);
    ++conPos; 
    lBasisUmsLfdJahr      = conpeek(inputParm, conPos);
    ++conPos; 
    lCSIncl               = conpeek(inputParm, conPos);
    ++conPos; 
    lSalesGroupMaster     = conpeek(inputParm, conPos);
    ++conPos; 
    conLen               = conpeek(inputParm, conPos);
    for (i=1; i <= conLen; i++)
    {
        ++conPos;
        conFirmen += conpeek(inputParm, conPos);
    }

    NDXUmsatzClassParmContract nDXUmsatzClassParmContract = NDXUmsatzClassParmContract::contractFromCon(inputParm);
    // #NDXBatchMultiThreading
    if (nDXUmsatzClassParmContract.parmBatchMultiThreadingStatus() == NDXBatchMultiThreadingStatus::DataCollection)
    {
        NDXMultiThreadingCreateTaskController controller;
        NDXBatchMultiThreadingContract contract = NDXBatchMultiThreadingContract::construct();
        NDXBatchProcessingTableHeader nDXBatchProcessingTableHeader = NDXBatchProcessingTableHeader::findActive(
            nDXUmsatzClassParmContract.parmLBasisUmsLfdJ() == NoYes::Yes ?
            NDXBatchProcessingType::SalesCurrentYear :
            NDXBatchProcessingType::SalesLastYear);
        contract.parmSysOperationExecutionMode(SysOperationExecutionMode::ReliableAsynchronous);
        contract.parmSignature(nDXBatchProcessingTableHeader.Signature);
        contract.parmUmsBasisLJ(nDXUmsatzClassParmContract.parmLBasisUmsLfdJ() == NoYes::Yes);
        controller = NDXMultiThreadingCreateTaskUmsController::instance(contract);
        controller.addCon2NDXBatchProcessingTable(nDXUmsatzClassParmContract);

        return;
    }

    nDX_JobManagerJobs = NDXJobMangerJobsClass::construct(NDXJobManagerJobId::getUmsVerband_L2);
    //TODO: DebuC austauschen der Winapi durch Protokolltabelle
    nDX_JobManagerJobs.openFileToWrite();
    nDX_JobManagerJobs.start();
    if (lAlliance)
    {
        actionStr = strfmt('Verband [%1]', alliance);
    }
    else
    {
        actionStr = strfmt('Verkaufsbereich [%1]', salesGroupId);
    }

    if (lThread)
    {
        ++conPos; 
        threadSession = conpeek(inputParm, conPos);
        //nDXThreadControl.ThreadSession = threadSession;
        nDXThreadControl.ThreadSession = SessionId();
        nDXThreadControl.MethodName    = staticmethodstr(NDXUmsatzClass, getUmsAlliance);
        nDXThreadControl.ClassName     = classstr(NDXUmsatzClass);
        nDXThreadControl = NDXThreadControl::findOrCreate(nDXThreadControl);

        threadControl = NDXTmpUmsatzClassThreadControl::find(umsSignature, NDXThreadTypes::getValuesCS, true);

    }

    if (lThread)
    {
        umsType = NDXGetUmsType::perAllianceThread;
    }
    else
    {
        umsType = NDXGetUmsType::perAlliance;
    }

    args.parmEnumType(enumnum(NDXGetUmsType));
    args.parmEnum(enum2int(umsType));
    args.parmLAlliance(lAlliance ? NDXNoYesBE::Yes : NDXNoYesBE::No);
    args.parmMaster(alliance);
    args.parmSalesGroupId(salesGroupId);
    args.parmDataVersion(dataVersion); 
    args.parmBatchWithMultithreading(nDXUmsatzClassParmContract.parmBatchWithMultithreading());

    if (lBasisUmsLfdJahr)
    {
        args.parmlBasisUmsLfdJ(NDXNoYesBE::Yes);
    }
    else
    {
        args.parmlBasisUmsLfdJ(NDXNoYesBE::No);
    }

    if (lCSIncl)
    {
        args.parmlCSIncl(NDXNoYesBE::Yes);
    }
    else
    {
        args.parmlCSIncl(NDXNoYesBE::No);
    }

    nDXUmsatzClass = NDXUmsatzClass::construct(args);
    nDXUmsatzClass.parmFirma(NDXHelperCommon::CompanyId2NDXCompany(curext()));

    // mit übergebenen Firmen initialisieren
    nDXUmsatzClass.initFirmen(conFirmen);

    nDXUmsatzClass.parmAccountNum(alliance);
    nDXUmsatzClass.parmMasterAlliance(alliance);

    nDXUmsatzClass.parmlAlliance(lAlliance);
    nDXUmsatzClass.parmSalesGroupId(salesGroupId);
    nDXUmsatzClass.parmNDXVerband().parmlSalesGroupMaster(lSalesGroupMaster);

    //nDX_UmsatzClass.parmlGetDataPerChild(true);
    nDXUmsatzClass.parmLThread(lThread);
    nDXVerband = nDXUmsatzClass.parmNDXVerband();
    nDXVerband.initFromNDXUmsatzClass(nDXUmsatzClass);
    if (nDXUmsatzClass.parmlAlliance())
    {
        nDXVerband.getChildsFromMaster(true);
    }
    else
    {
        nDXVerband.getChildsFromSalesGroupId(true, nDXUmsatzClass.parmConCompanies(), umsSignature);
    }

    nDXUmsatzClass.parmNAnzChilds(nDXVerband.parmNAnzChilds());
    nDXUmsatzClass.parmRecIdNDXBatchProcessingTable(nDXUmsatzClassParmContract.parmRecIdNDXBatchProcessingTable());

    nDX_JobManagerJobs.setAction('Zentrallager ermitteln', actionStr);
    nDXVerband.getCSFromMaster(nDXUmsatzClass.parmConFirmen());


    //*** Artikelgruppenumsatz ermitteln
    {
        signatureValuesArtGrp = NDXHelperCommon::Signature();
        nDXUmsatzClass.parmSignatureArtGrp(signatureValuesArtGrp);
        nDX_JobManagerJobs.setAction('Artikelgruppenumsatz ermitteln', actionStr);
        taskArtGrp     = NDXUmsatzClassThread::runGetValuesArtGrp(nDXUmsatzClass);
        NDXThreadErrors::increaseCounter(signatureValuesArtGrp, taskArtGrp ? taskArtGrp.Status : System.Threading.Tasks.TaskStatus::RanToCompletion);
    }

    //*** Kundenumsatz
    {
        for (i=1; i<=NDXThreadConstants::MaxStatusLoops; i++)
        {
            signatureValuesCust = NDXHelperCommon::Signature();
            nDXUmsatzClass.parmSignatureCust(signatureValuesCust);
            nDX_JobManagerJobs.setAction('Kundenumsatz ermitteln', actionStr);

            taskCust       = NDXUmsatzClassThread::runGetValuesCust(nDXUmsatzClass);

            if (!lThread || taskCust.Status != System.Threading.Tasks.TaskStatus::Canceled)
            {
                break;
            }
            sleep(1000);
        }
        NDXThreadErrors::increaseCounter(signatureValuesCust, taskCust ? taskCust.Status : System.Threading.Tasks.TaskStatus::RanToCompletion);

        // zunächst müssen die Umsatzdaten der Customer ermittelt worden sein, bevor die Zentrallageranteile berechnet werden
        if (lThread)
        {
            while (taskCust.Status != System.Threading.Tasks.TaskStatus::RanToCompletion)
            {
                NDXThreadErrors::increaseCounter(signatureValuesCust, taskCust.status);
                sleep(1000);
                if (NDXBatchProcessingParameters::throwExceptionTaskUms())
                {
                    throw error("@NDX:NDXForcedTerminationRunGetValuesCust");
                }
            }
        }
    }

    //*** Zentrallager-Umsatzanteile
    {
        signatureValuesCS = NDXHelperCommon::Signature();
        nDXUmsatzClass.parmSignatureCS(signatureValuesCS);
        nDX_JobManagerJobs.setAction('Zentrallager-Umsatz-Anteile ermitteln', actionStr);
        for (i=1; i<=NDXThreadConstants::MaxStatusLoops; i++)
        {
            taskCS         = NDXUmsatzClassThread::runGetValuesCS(nDXUmsatzClass);
            if (!lThread || taskCS.Status != System.Threading.Tasks.TaskStatus::Canceled)
            {
                break;
            }
            sleep(1000);
        }


        NDXThreadErrors::increaseCounter(signatureValuesCS, taskCS ? taskCS.Status : System.Threading.Tasks.TaskStatus::RanToCompletion);

        // Wurden alle Umsätze aller Zentrallager ermittelt?
        if (lThread)
        {
            while (taskCS.Status != System.Threading.Tasks.TaskStatus::RanToCompletion)
            {

                NDXThreadErrors::increaseCounter(signatureValuesCS, taskCS.Status);
                sleep(1000);
                if (NDXBatchProcessingParameters::throwExceptionTaskUms())
                {
                    throw error("@NDX:NDXForcedTerminationRunGetValuesCS");
                }
            }
        }
    }

    // wurden alle Zentrallager-Debitoren berücksichtigt?
    //TODO DEBUC: Threadfähigkeit programmieren
    //if (lThread)
    //warning("nDX_UmsatzClass.getCSExclPct() aus NDX_UmsatzClass.getUmsAlliance() wurde noch nicht Threadfähig programmiert!");
    //nDXUmsatzClass.getCSExclPct(nDXUmsatzClass.parmYearVJ());

    // Wurden alle Umsätze aller Artikelgruppen ermittelt?
    if (lThread)
    {
        while (taskArtGrp.status != System.Threading.Tasks.TaskStatus::RanToCompletion
            && taskArtGrp.status != System.Threading.Tasks.TaskStatus::Canceled
            && taskArtGrp.status != System.Threading.Tasks.TaskStatus::Faulted)
        {
            NDXThreadErrors::increaseCounter(signatureValuesArtGrp, taskArtGrp.Status);
            sleep(1000);
        }
    }

    if (lThread)
    {
        nDXThreadControl.stop();
    }

    nDX_JobManagerJobs.ende();
    return;
}

