/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "custAccount">CustAccount</param>
/// <returns>CustTable</returns>
CustTable getCustTableFromCustAccount(CustAccount custAccount)
{
    Query                                   q;
    QueryRun                                qr;
    QueryBuildDataSource                    qbds1;
    ;
    q = new Query();
    q.allowCrossCompany(true);
    q.addCompanyRange(firmaAsCompanyId ? firmaAsCompanyId : NDXHelperCommon::NDXCompanys2CompanyId(NDXCompanyBE::Niedax));
    qbds1 = q.addDataSource(tablenum(CustTable));
    qbds1.firstOnly(true);
    qbds1.addSortField(fieldnum(CustTable, AccountNum), SortOrder::Ascending);
    qbds1.addRange(fieldnum(CustTable, AccountNum)).value(custAccount);
    qr = new QueryRun(q);
    qr.next();
    return qr.get(tablenum(CustTable));
}

