        firma == NDXCompanyBE::WithoutAssignment)
    {
        lfirma = NDXCompanyBE::Niedax;
    }
    return NDXKumUmsCustWithSales::custTableFromAccount(accountNum, lfirma);
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <returns>Map</returns>
static Map getFieldPrefixFromNDX_MonatBE()
{
    Map             l_map = new Map(Types::Enum, Types::String);
    DictEnum        enum;
    NDXMonthBE      monatBE;
    int             i;
    str             prefix;
    ;
    enum = new DictEnum(enumnum(NDXMonthBE));

    for (i = 0; i < enum.values(); i++)
    {
        monatBE = enum.index2Value(i);
        prefix  = strfmt('%1%2', ((i < 10) ? '0' : ''), i);
        l_map.insert(monatBE, prefix);
    }
    return l_map;
}

/// <summary>
