NDXUmsatz VUAJahrNDXTmpKumUmsCustArtGrp(NDXTmpKumUmsCustArtGrp nDX_TmpKumUmsCustArtGrp)
{
    int             i;
    NDXUmsatz      umsatz;
    ;
    if (nDXUmsatzAbschluss.parmJahr() <= yearlfdJ)
    {
        // Werte bis zum Abschlussmonat ermitteln
        for (i = 1; i <= nDXUmsatzAbschluss.parmMonat(); i++)
        {
            switch (i)
            {
                case 1 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.VU01; 
                    break;
                case 2 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.VU02; 
                    break;
                case 3 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.VU03; 
                    break;
                case 4 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.VU04; 
                    break;
                case 5 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.VU05; 
                    break;
                case 6 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.VU06; 
                    break;
                case 7 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.VU07; 
                    break;
                case 8 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U08; 
                    break;
                case 9 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U09; 
                    break;
                case 10: 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U10; 
                    break;
                case 11: 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U11; 
                    break;
                case 12: 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U12; 
                    break;
            }
        }
        return umsatz;
    }
    else
    {
        return nDX_TmpKumUmsCustArtGrp.getUmsLfdJahr();
    }
}

/// <summary>
