/// </summary>
/// <param name = "party">RefRecId</param>
/// <param name = "firma">NDXCompanys</param>
/// <returns>CustTable</returns>
static CustTable getCustTableFromPartyId(RefRecId party, NDXCompanys firma)
{
    container       conUK;
    CustTable       custTable;
    NDXCompanys     lfirma;
    ;
    lfirma = firma;
    if (firma == NDXCompanyBE::AllCompanies ||
        firma == NDXCompanyBE::WithoutAssignment)
    {
        lfirma = NDXCompanyBE::Niedax;
    }

    conUK += NDXHelperCommon::NDXCompanys2CompanyId(lfirma);
    select crosscompany:conUK custTable where custTable.Party == party;
    return custTable;
}

