                case 4 : 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU04; 
                    break;
                case 5 : 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU05; 
                    break;
                case 6 : 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU06; 
                    break;
                case 7 : 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU07; 
                    break;
                case 8 : 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU08; 
                    break;
                case 9 : 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU09; 
                    break;
                case 10: 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU10; 
                    break;
                case 11: 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU11; 
                    break;
                case 12: 
                    umsatz += nDX_TmpCSAllianceArtGrp.VU12; 
                    break;
            }
        }
        return umsatz;
    }
    else
    {
        return nDX_TmpCSAllianceArtGrp.VUJahr();
    }
}

/// <summary>
