                    break;
                case 6 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U06; 
                    break;
                case 7 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U07; 
                    break;
                case 8 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U08; 
                    break;
                case 9 : 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U09; 
                    break;
                case 10: 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U10; 
                    break;
                case 11: 
                    umsatz += nDX_TmpKumUmsCustArtGrp.U11; 
