    else
    {
        return nDX_TmpKumUmsCustArtGrp.getUmsLfdJahr();
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "monat">NDXMonthBE</param>
/// <param name = "jahr">int</param>
/// <param name = "lCheckKumUmsCustArtGrp">boolean</param>
static void fillNDXKumUmsCustArtGrpFromLiveSales(NDXMonthBE monat, int jahr, boolean lCheckKumUmsCustArtGrp = true)
{
    NDXKumUmsCust           nDX_KumUmsCust;
    NDXUmsCust              nDX_UmsCust, nDX_UmsCustCompany;
    NDXUmsCust_ArtGrp       nDX_UmsCust_ArtGrp, nDX_UmsCust_ArtGrpCompany ;
    NDXKumUmsCustArtGrp     nDX_KumUmsCustArtGrp, l_nDX_KumUmsCustArtGrp;

    NDXCompanyBE            firma;
    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds;
    ;

    info(strfmt("@NDX:NDXSalesVolumeInKumUmsCustArtGrp", NDXHelperCommon::seconds2Str()));                   // [%1] START: Umsätze in NDX_KumUmsCustArtGrp aus Livedaten verbuchen
    // Prüfen, ob alle Datensätze in NDX_KumUmsCustArtGrp einen CustAccount zugeordnet haben
    // in NDX_KumUmsCust wurden die Referenzen bereits bereinigt.
    // Daher werden diese Daten als Basis genutzt
    if (lCheckKumUmsCustArtGrp)
    {
        info(strfmt("@NDX:NDXCheckCustAccountOfKumUmsCustArtGrp", NDXHelperCommon::seconds2Str()));               // [%1] Prüfung, ob alle Datensätze in NDX_KumUmsCustArtGrp einen CustAccount zugeordnet haben
        while select  nDX_KumUmsCustArtGrp
        where     !nDX_KumUmsCustArtGrp.CustAccount
        join      nDX_KumUmsCust
            where nDX_KumUmsCust.KdNr == nDX_KumUmsCustArtGrp.KdNr
        {
            ttsbegin;
            l_nDX_KumUmsCustArtGrp = NDXKumUmsCustArtGrp::findOrCreate(nDX_KumUmsCustArtGrp, true);

            l_nDX_KumUmsCustArtGrp.CustAccount    = nDX_KumUmsCust.CustAccount;
            if (!l_nDX_KumUmsCustArtGrp.CompanyId)
            {
                l_nDX_KumUmsCustArtGrp.CompanyId  = NDXHelperCommon::NDXCompanys2CompanyId(l_nDX_KumUmsCustArtGrp.Companys);
            }
            l_nDX_KumUmsCustArtGrp.update();
            ttscommit;
        }
    }

    // Zunächst Umsätze des Monats initialisieren
    info(strfmt("@NDX:NDXSetSalesVolumeToZero", NDXHelperCommon::seconds2Str(), monat, jahr));      // [%1] Umsätze des Monats [%2-%3] auf 0 setzen
    q       = new Query();
    qbds    = q.addDataSource(tablenum(NDXKumUmsCustArtGrp));
    qbds.update(true);
    qbds.addRange(fieldnum(NDXKumUmsCustArtGrp, jahr)).value(QueryValue(jahr));
    qr      = new QueryRun(q);
    while (qr.next())
    {
        ttsbegin;
        nDX_KumUmsCustArtGrp  = qr.get(tablenum(NDXKumUmsCustArtGrp));
        nDX_KumUmsCustArtGrp.initUmsMonat(monat);
        nDX_KumUmsCustArtGrp.update();
        ttscommit;

    }

    // Umsätze zubuchen
    info(strfmt("@NDX:NDXPostSalesVolumeOfMonth", NDXHelperCommon::seconds2Str(), monat, jahr));      // [%1] Umsätze des Monats [%2-%3] zubuchen
    while select    nDX_UmsCust_ArtGrpCompany
    group by    CompanyId
        join    nDX_UmsCustCompany
        where   nDX_UmsCustCompany.InvoiceId    == nDX_UmsCust_ArtGrpCompany.InvoiceId  &&
                nDX_UmsCustCompany.Month        == monat                                &&
                nDX_UmsCustCompany.Jahr         == jahr
    {
        firma = NDXHelperCommon::CompanyId2NDXCompany(nDX_UmsCust_ArtGrpCompany.CompanyId);
        changecompany(nDX_UmsCust_ArtGrpCompany.CompanyId)
        {
            nDX_UmsCust_ArtGrp = null;

            while select nDX_UmsCust_ArtGrp
            where       nDX_UmsCust_ArtGrp.CompanyId   == nDX_UmsCust_ArtGrpCompany.CompanyId
            join        nDX_UmsCust
                where   nDX_UmsCust.InvoiceId   == nDX_UmsCust_ArtGrp.InvoiceId     &&
                        nDX_UmsCust.Month       == monat                            &&
                        nDX_UmsCust.Jahr        == jahr
            {
                // Umsatz
                ttsbegin;
                nDX_KumUmsCustArtGrp = null;
                nDX_KumUmsCustArtGrp.CustAccount  = nDX_UmsCust.OrderAccount;
                nDX_KumUmsCustArtGrp.ARTGRP       = nDX_UmsCust_ArtGrp.GoodsId;
                nDX_KumUmsCustArtGrp.CompanyId    = nDX_UmsCust_ArtGrp.CompanyId;
                nDX_KumUmsCustArtGrp.Jahr         = jahr;
                nDX_KumUmsCustArtGrp.Companys        = firma;
                nDX_KumUmsCustArtGrp = NDXKumUmsCustArtGrp::findOrCreate(nDX_KumUmsCustArtGrp, true);
                if (!nDX_KumUmsCustArtGrp.KdNr)
                {
                    nDX_KumUmsCustArtGrp.KdNr = str2int(nDX_KumUmsCustArtGrp.CustAccount);
                }
                nDX_KumUmsCustArtGrp.addUmsFromNDXUmsCust_ArtGrp(monat, nDX_UmsCust_ArtGrp);
                nDX_KumUmsCustArtGrp.update();
                ttscommit;
            }
        }
    }
    info(strfmt("@NDX:NDXSalesVolumeInKumUmsCustArtGrpEnd", NDXHelperCommon::seconds2Str()));                   // [%1] ENDE: Umsätze in NDX_KumUmsCustArtGrp aus Livedaten verbuchen

    // Übernahme der Live-Daten in Parameter speichern
    NDXUmsatzParametersGlobal::setLastSalesImport();
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
static void checkCustAccountRef()
{
    NDXKumUmsCust          nDX_KumUmsCust;
    NDXKumBonCust          nDX_KumBonCust;
    NDXKumUmsCustArtGrp    nDX_KumUmsCustArtGrp;
    NDXKumUmsCustWithSales nDX_KumUmsCustWithSales;
    CustTable               custTable;
    SalesTable              salesTable;
    NDXUmsatzClass         nDX_UmsatzClass;

    container               conCompany;
    container               conFirmen;
    int                     i;
    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds, qbds2, qbds3;
    ;

    //--> 1.1: NDX/PAFFH/NDX_TASK1235003633/17.02.2014
    // Sind für alle Debitoren der Umsatz-UK's Referenzen vorhanden?
    nDX_UmsatzClass = NDXUmsatzClass::construct();
    conFirmen = nDX_UmsatzClass.parmConFirmen();
    for (i=1; i <= conlen(conFirmen); i++)
    {
        changecompany(NDXHelperCommon::NDXCompanys2CompanyId(conpeek(conFirmen,i)))
        {
            q = new Query();
            qbds = q.addDataSource(tablenum(SalesTable));
            qbds.orderMode(OrderMode::GroupBy);
            //qbds.addOrderByField(fieldnum(SalesTable, CustAccount));
            qbds.addGroupByField(fieldnum(SalesTable, CustAccount));
            qbds.addSortField(fieldnum(SalesTable, CustAccount));

            qbds3 = qbds.addDataSource(tablenum(CustTable));
            qbds3.joinMode(JoinMode::InnerJoin);
            qbds3.addLink(fieldnum(SalesTable, CustAccount), fieldnum(CustTable, AccountNum));
            qbds3.addGroupByField(fieldnum(CustTable, dataAreaId));
            qbds3.addGroupByField(fieldnum(CustTable, AccountNum));
            qbds3.addGroupByField(fieldnum(CustTable, Party));
            qbds3.fetchMode(QueryFetchMode::One2One);

            qbds2 = qbds.addDataSource(tablenum(NDXKumUmsCustWithSales));
            qbds2.addLink(fieldnum(SalesTable, dataAreaId), fieldnum(NDXKumUmsCustWithSales, CompanyId));
            qbds2.addLink(fieldnum(SalesTable, CustAccount), fieldnum(NDXKumUmsCustWithSales, CustAccount));
            qbds2.joinMode(JoinMode::NoExistsJoin);
            qbds2.fetchMode(QueryFetchMode::One2One);
            qr = new QueryRun(q);

            while (qr.next())
            {
                salesTable = qr.get(tablenum(SalesTable));
                custTable  = qr.get(tablenum(CustTable));
                if (custTable.AccountNum)
                {
                    nDX_KumUmsCustWithSales.clear();
                    nDX_KumUmsCustWithSales.CompanyId = custTable.dataAreaId;
                    nDX_KumUmsCustWithSales.NameAlias   = DirPartyTable::findRec(custTable.Party).NameAlias;
                    nDX_KumUmsCustWithSales.Company       = conpeek(conFirmen,i);
                    nDX_KumUmsCustWithSales.CustAccount = custTable.AccountNum;
                    nDX_KumUmsCustWithSales.insert();
                }
            }
        }
    }

    // sind zu allen Monatsumsatz-Datensätzen die Account-Referenzen vorhanden?
    while select forUpdate  nDX_KumUmsCust
    where               !nDX_KumUmsCust.CustAccount
    {
        conCompany = connull();
        conCompany += nDX_KumUmsCust.CompanyId;
        select firstonly crosscompany:conCompany custTable where custTable.AccountNum == int2str(nDX_KumUmsCust.KdNr);
        if (custTable)
        {
            ttsbegin;
            nDX_KumUmsCust.CustAccount  = custTable.AccountNum;
            nDX_KumUmsCust.update();
            ttscommit;
        }
        else
        {
            warning(strfmt("@NDX:NDXMissingCustomerRef", nDX_KumUmsCust.CompanyId, nDX_KumUmsCust.KdNr, tableid2name(nDX_KumUmsCust.TableId))); // Für Kunde [%1-%2] wurde keine Kundenreferenz in [%3] gefunden
        }
    }

    // sind zu allen MonatsBonus-Datensätzen die Account-Referenzen vorhanden?
    while select forUpdate  nDX_KumBonCust
    where               !nDX_KumBonCust.CustAccount
    {
        conCompany = connull();
        conCompany += nDX_KumBonCust.CompanyId;
        select firstonly crosscompany:conCompany custTable where custTable.AccountNum == int2str(nDX_KumBonCust.KdNr);
        if (custTable)
        {
            ttsbegin;
            nDX_KumBonCust.CustAccount  = custTable.AccountNum;
            nDX_KumBonCust.update();
            ttscommit;
        }
        else
        {
            warning(strfmt("@NDX:NDXMissingCustomerRef", nDX_KumBonCust.CompanyId, nDX_KumBonCust.KdNr, tableid2name(nDX_KumBonCust.TableId))); // Für Kunde [%1-%2] wurde keine Kundenreferenz in [%3] gefunden
        }

    }


    // sind für alle Artikelgruppenumsätze die Referenzen vorhanden?
    while select forUpdate  nDX_KumUmsCustArtGrp
    where               !nDX_KumUmsCustArtGrp.CustAccount
    {
        // ist die CompanyId zugeordnet?
        if (!nDX_KumUmsCustArtGrp.CompanyId)
        {
            nDX_KumUmsCustArtGrp.CompanyId = NDXHelperCommon::NDXCompanys2CompanyId(nDX_KumUmsCustArtGrp.Companys);
        }

        conCompany = connull();
        conCompany += nDX_KumUmsCustArtGrp.CompanyId;
        select firstonly crosscompany:conCompany custTable where custTable.AccountNum == int2str(nDX_KumUmsCustArtGrp.KdNr);
        if (custTable)
        {
            ttsbegin;
            nDX_KumUmsCustArtGrp.CustAccount  = custTable.AccountNum;
            nDX_KumUmsCustArtGrp.update();
            ttscommit;
        }
        else
        {
            nDX_KumUmsCustWithSales = NDXKumUmsCustWithSales::findKdNr(nDX_KumUmsCustArtGrp.KdNr, nDX_KumUmsCustArtGrp.Companys);
            if (nDX_KumUmsCustWithSales.CustAccount)
            {
                ttsbegin;
                nDX_KumUmsCustArtGrp.CustAccount  = nDX_KumUmsCustWithSales.CustAccount;
                nDX_KumUmsCustArtGrp.update();
                ttscommit;
            }
        }
        if (!nDX_KumUmsCustArtGrp.CustAccount &&
        nDX_KumUmsCustArtGrp.Jahr > 2007  &&
        nDX_KumUmsCustArtGrp.getUmsJahr())
        {
            warning(strfmt("@NDX:NDXMissingCustomerRef", nDX_KumUmsCustArtGrp.CompanyId, nDX_KumUmsCustArtGrp.KdNr, tableid2name(nDX_KumUmsCustArtGrp.TableId)));
        }

    }

}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "dateFrom">InvoiceDate</param>
/// <param name = "dateTo">InvoiceDate</param>
/// <param name = "voucher">Voucher</param>
static void fillLiveSales(InvoiceDate   dateFrom  = DateStartMth(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())),
    InvoiceDate   dateTo    = dateEndMth(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())),
                      Voucher       voucher   = '')
{
    const str SofortbonusId = 'Sofort_Bon';
    const str SofortbonusLike = 'Sofort_B*';
    InventTableModule       inventTableModule;
    InventTable             inventTable;
    CustInvoiceJour         custInvoiceJour;
    CustInvoiceTrans        custInvoiceTrans;
    MarkupTrans             markupTrans, markupTrans2, markupTrans3, markupTransLine;
    MarkupTable             markupTable;
    InventTrans             inventTrans;


    NDXUmsCust_ArtGrp       nDX_UmsCust_ArtGrp;
    NDXUmsCust              nDX_UmsCust;

    NDXUmsatzClassArgs      nDX_UmsatzClassArgs;
    NDXUmsatzClass          nDX_UmsatzClass;
    NDXGetUmsType           umsType;
    container               conCompanies;
    int                     i;
    dataAreaId              company;
    InventLineDiscCode      lineDiscCode;

    Query                   qHead, qPos;
    QueryRun                qrHead, qrPos;
    QueryBuildDataSource    qbdsHead, qbdsHead2, qbdsPos;
    QueryBuildFieldList     fieldsHead;
    AmountCur               amountSum;
    AmountCur               sofbonSum;
    CostAmountPosted        costAmountPosted, costAmountPostedSum;
    CostAmountAdjusted      costAmountAdjusted, costAmountAdjustedSum;
    Qty                     qty;

    ;
    umsType             = NDXGetUmsType::perCustomer;
    nDX_UmsatzClassArgs = new NDXUmsatzClassArgs();
    nDX_UmsatzClassArgs.parmEnumType(enumnum(NDXGetUmsType));
    nDX_UmsatzClassArgs.parmEnum(enum2int(umsType));
    nDX_UmsatzClass     = NDXUmsatzClass::construct(nDX_UmsatzClassArgs);
    conCompanies        = nDX_UmsatzClass.parmConCompanies();

    if (!confind(conCompanies, NDXHelperCommon::NDXCompanys2CompanyId(NDXCompanyBE::Niedergesaess)))
    {
        conCompanies += NDXHelperCommon::NDXCompanys2CompanyId(NDXCompanyBE::Niedergesaess);
    }
    if (!confind(conCompanies, NDXHelperCommon::NDXCompanys2CompanyId(NDXCompanyBE::Fintech)))
    {
        conCompanies += NDXHelperCommon::NDXCompanys2CompanyId(NDXCompanyBE::Fintech);
    }

    info(strfmt("@NDX:NDXProcessSalesDataForPeriod", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), dateFrom, dateTo));        // [%1] START: Live-Umsatzdaten des Zeitraums [%2 - %3] verarbeiten

    if (!voucher)
    {
        info(strfmt("@NDX:NDXDeleteCapturedDataUmsCustArtGrp", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))));                      // [%1] Erfasste Daten in NDX_UmsCust_ArtGrp löschen
        //Erfasste Daten des Zeitraums bereinigen
        delete_from nDX_UmsCust_ArtGrp
        exists join nDX_UmsCust
            where   nDX_UmsCust.CompanyId   == nDX_UmsCust_ArtGrp.CompanyId &&
                    nDX_UmsCust.InvoiceId   == nDX_UmsCust_ArtGrp.InvoiceId &&
                    nDX_UmsCust.InvoiceDate >= dateFrom                     &&
                    nDX_UmsCust.InvoiceDate <= dateTo;

        info(strfmt("@NDX:NDXDeleteCapturedDataUmsCust", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))));                      // [%1] Erfasste Daten in NDX_UmsCust löschen
        delete_from     nDX_UmsCust
            where   nDX_UmsCust.InvoiceDate >= dateFrom                     &&
                    nDX_UmsCust.InvoiceDate <= dateTo;
    }

    for (i = 1; i <= conlen(conCompanies); i++)
    {
        company = conpeek(conCompanies, i);
        changecompany(company)
        {
            inventTable         = null;
            inventTableModule   = null;
            custInvoiceJour     = null;
            custInvoiceTrans    = null;
            markupTable         = null;
            markupTrans         = null;
            markupTrans2        = null;
            markupTrans3        = null;
            markupTransLine     = null;
            inventTrans         = null;

            // Daten sammeln
            info(strfmt("@NDX:NDXProcessJournalizedSalesVolumeInCompany", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), company));         // [%1] Journalisierte Umsätze im UK [%2] verarbeiten
            markupTable = markupTable::find(MarkupModuleType::Cust, SofortbonusId);

            qHead       = new Query();
            qbdsHead    = qHead.addDataSource(tablenum(CustInvoiceJour));
            qbdsHead2   = qbdsHead.addDataSource(tablenum(custInvoiceTrans));
            qbdsHead2.addRange(fieldnum(custInvoiceTrans, SalesId)).value(SysQuery::valueNotEmptyString());
            qbdsHead2.joinMode(JoinMode::ExistsJoin);
            qbdsHead2.addLink(fieldnum(custInvoiceJour, InvoiceId), fieldnum(custInvoiceTrans, InvoiceId));

            qbdsHead.addRange(fieldnum(custInvoiceJour, InvoiceId)).value(SysQuery::valueNotEmptyString());
            qbdsHead.addRange(fieldnum(custInvoiceJour, InvoiceDate)).value(strfmt('%1..%2', dateFrom, dateTo));
            qbdsHead.addRange(fieldnum(custInvoiceJour, SalesType)).value(SysQuery::valueNot(SalesType::Journal));
            if (voucher)
            {
                qbdsHead.addRange(fieldnum(custInvoiceJour, LedgerVoucher)).value(voucher);
            }

            fieldsHead  = qbdsHead.fields();
            fieldsHead.addField(fieldnum(CustInvoiceJour, InvoiceId));
            fieldsHead.addField(fieldnum(CustInvoiceJour, InvoiceAccount));
            fieldsHead.addField(fieldnum(CustInvoiceJour, OrderAccount));
            fieldsHead.addField(fieldnum(CustInvoiceJour, InvoiceDate));
            fieldsHead.addField(fieldnum(CustInvoiceJour, SalesBalance));
            fieldsHead.addField(fieldnum(CustInvoiceJour, RecId));
            fieldsHead.addField(fieldnum(CustInvoiceJour, SalesId));
            fieldsHead.addField(fieldnum(custInvoiceJour, SalesBalanceMST)); 

            qrHead = new QueryRun(qHead);

            while (qrHead.next())
            {
                custInvoiceJour = qrHead.get(tablenum(CustInvoiceJour));
                nDX_UmsCust = NDXUmsCust::find(company, custInvoiceJour.InvoiceId, custInvoiceJour.RecId, true);
                select firstonly markupTrans
                where   markupTrans.TransTableId    == custInvoiceJour.TableId   &&
                        markupTrans.TransRecId      == custInvoiceJour.RecId     &&
            //            markupTrans.MarkupCode      == markupTable.MarkupCode;
                markupTrans.MarkupCode      like SofortbonusLike;


                // sonstige Zuschläge
                //TODO: DebuC Umsatzauswertung Fremdwährung
                select      sum(CalculatedAmount) from markupTrans2
                group by TransTableId, TransRecId
                where   markupTrans2.TransTableId    == custInvoiceJour.TableId   &&
                        markupTrans2.TransRecId      == custInvoiceJour.RecId
                notexists join markupTrans3
                where   markupTrans3.TransTableId    == custInvoiceJour.TableId   &&
                        markupTrans3.TransRecId      == custInvoiceJour.RecId     &&
                        markupTrans3.MarkupCode      like SofortbonusLike;

                ttsbegin;

                nDX_UmsCust.CompanyId       = company;
                nDX_UmsCust.InvoiceId       = custInvoiceJour.InvoiceId;
                nDX_UmsCust.SalesId         = custInvoiceJour.SalesId;
                nDX_UmsCust.RefRecId        = custInvoiceJour.RecId;
                nDX_UmsCust.InvoiceAccount  = custInvoiceJour.InvoiceAccount;
                nDX_UmsCust.OrderAccount    = custInvoiceJour.OrderAccount;
                nDX_UmsCust.InvoiceDate     = custInvoiceJour.InvoiceDate;
                //TODO: DebuC Umsatzauswertung Fremdwährung
                nDX_UmsCust.SalesBalance    = custInvoiceJour.SalesBalanceMST + markupTrans.CalculatedAmount; // Rechnungswert - Bonus
                nDX_UmsCust.Sofortbonus     = markupTrans.Value;
                //TODO: DebuC Umsatzauswertung Fremdwährung
                nDX_UmsCust.SofortbonusWert = markupTrans.CalculatedAmount;
                nDX_UmsCust.Jahr            = year(nDX_UmsCust.InvoiceDate);
                nDX_UmsCust.Month           = mthofyr(nDX_UmsCust.InvoiceDate);

                //CustInvoiceTrans durchlaufen
                qPos    = new Query();
                qbdsPos = qPos.addDataSource(tablenum(CustInvoiceTrans));
                qbdsPos.addRange(fieldnum(CustInvoiceTrans, SalesId)).value(custInvoiceJour.SalesId);
                qbdsPos.addRange(fieldnum(CustInvoiceTrans, InvoiceId)).value(custInvoiceJour.InvoiceId);
                qbdsPos.addRange(fieldnum(CustInvoiceTrans, InvoiceDate)).value(QueryValue(custInvoiceJour.InvoiceDate));
                qbdsPos.addRange(fieldnum(CustInvoiceTrans, numberSequenceGroup)).value(custInvoiceJour.numberSequenceGroup);
                qrPos   = new QueryRun(qPos);
                amountSum               = 0;
                sofbonSum               = 0;
                costAmountAdjustedSum   = 0;
                costAmountPostedSum     = 0;
                while (qrPos.next())
                {
                    custInvoiceTrans = qrPos.get(tablenum(CustInvoiceTrans));

                    if (!custInvoiceTrans.ItemId)
                    {
                        info(strfmt("@NDX:NDXDocumentInheritsPositionWithoutItemNumber", custInvoiceTrans.InvoiceId));                   // Beleg [%1] mit Position ohne Artikelnummer
                    }
                    inventTable         = inventTable::find(custInvoiceTrans.ItemId);
                    inventTableModule   = inventTableModule::find(custInvoiceTrans.ItemId, ModuleInventPurchSales::Sales);
                    lineDiscCode        = inventTableModule.LineDisc;
                    //--> 1.3: NDX/PaffH/18.05.2011
                    if (!lineDiscCode)
                    {
                        info(strfmt("@NDX:NDXItemWithoutDiscountGroup" , custInvoiceTrans.ItemId, company, custInvoiceTrans.InvoiceId, custInvoiceTrans.LineAmount));       // Artikel [%1] aus Rechnung [%2-%3] ohne Positionsrabattgruppe; Umsatz [%4]
                        nDX_UmsCust.ohnePosRabGrp += custInvoiceTrans.LineAmount;
                    }
                    nDX_UmsCust_ArtGrp  = NDXUmsCust_ArtGrp::find(company, custInvoiceJour.SalesId, custInvoiceTrans.InvoiceId, lineDiscCode, true);
                    if (!nDX_UmsCust_ArtGrp)
                    {
                        nDX_UmsCust_ArtGrp.CompanyId    = company;
                        nDX_UmsCust_ArtGrp.SalesId      = custInvoiceJour.SalesId;
                        nDX_UmsCust_ArtGrp.InvoiceId    = custInvoiceTrans.InvoiceId;
                        nDX_UmsCust_ArtGrp.GoodsId      = lineDiscCode;
                    }

                    select firstonly markupTransLine
                    where   markupTransLine.TransTableId    == custInvoiceTrans.TableId   &&
                            markupTransLine.TransRecId      == custInvoiceTrans.RecId     &&
                            markupTransLine.MarkupCode      like SofortbonusLike;
                    //TODO: DebuC Umsatzauswertung Fremdwährung
                    sofbonSum += markupTransLine.CalculatedAmount;
                    nDX_UmsCust_ArtGrp.LineAmount       += custInvoiceTrans.LineAmountMST;
                    amountSum                           += custInvoiceTrans.LineAmountMST;

                    // InventTrans-Summen ermitteln
                    [costAmountPosted, CostAmountAdjusted, qty] = custInvoiceTrans.NDXinventCostAmount();
                    if ((qty * -1) != custInvoiceTrans.Qty) // InventTransid [%1]; InvoiceId [%4] Menge aus InventTrans [%2] entspricht nicht der aus CustInvoiceTrans [%3]
                    {
                        info(strfmt("@NDX:NDXQuantityDiffInventTransCustInvoiceTrans", custInvoiceTrans.InventTransId, qty, custInvoiceTrans.Qty, custInvoiceTrans.InvoiceId ));
                    }
                    nDX_UmsCust_ArtGrp.CostAmountPosted     += costAmountPosted;
                    nDX_UmsCust_ArtGrp.CostAmountAdjusted += CostAmountAdjusted;
                    costAmountPostedSum                     += costAmountPosted;
                    costAmountAdjustedSum                   += CostAmountAdjusted;

                    nDX_UmsCust_ArtGrp.write();
                }
                if (sofbonSum)
                {
                    nDX_UmsCust.SofortbonusWert += sofbonSum;
                    nDX_UmsCust.SalesBalance    += sofbonSum;
                }

                if (!nDX_UmsCust.Sofortbonus && markupTransLine.Value)
                {
                    nDX_UmsCust.Sofortbonus = markupTransLine.Value;
                }

                if (amountSum != nDX_UmsCust.SalesBalance - nDX_UmsCust.SofortbonusWert)
                {
                    info(strfmt("@NDX:NDXDifferenceLineAmount", nDX_UmsCust.InvoiceId, (nDX_UmsCust.SalesBalance - nDX_UmsCust.SofortbonusWert) - amountSum));      // Beleg [%1] Differenz LineAmount [%2]
                }

                nDX_UmsCust.CostAmountAdjusted    = costAmountAdjustedSum;
                nDX_UmsCust.CostAmountPosted        = costAmountPostedSum;

                nDX_UmsCust.write();
                ttscommit;

            }
        }
    }
    info(strfmt("@NDX:NDXProcessSalesDataForPeriodEnd", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), dateFrom, dateTo));        // [%1] ENDE: Live-Umsatzdaten des Zeitraums [%2 - %3] verarbeiten

    if (voucher)
    {
        info("@NDX:NDXDataPreparedForOneDocument");               // Achtung: Daten wurden nur für einen Beleg aufbereitet. Es ist eine neue zeitraumbasierte Aufbereitung notwendig!
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "monat">NDXMonthBE</param>
/// <param name = "jahr">int</param>
/// <param name = "lCheckKumUmsCust">boolean</param>
static void fillNDXKumUmsCustFromLiveSales(NDXMonthBE monat, int jahr, boolean lCheckKumUmsCust = true)
{
    NDXUmsCust             nDX_UmsCust, nDX_UmsCustCompany ;
    NDXKumUmsCust          nDX_KumUmsCust, l_nDX_KumUmsCust;
    NDXKumBonCust          nDX_KumBonCust, l_nDX_KumBonCust;

    NDXCompanyBE            firma;
    int                     nErrors = 0;
    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds;
    ;
    info(strfmt("@NDX:NDXSalesVolumeInKumUmsCustArtGrp", NDXHelperCommon::seconds2Str()));                   // [%1] START: Umsätze in NDX_KumUmsCust aus Livedaten verbuchen

    // Prüfen, ob alle Datensätze in NDX_KumUmsCust einen CustAccount zugeordnet haben
    if (lCheckKumUmsCust)
    {
        info(strfmt("@NDX:NDXCheckCustAccountOfKumUmsCust", NDXHelperCommon::seconds2Str()));               // [%1] Prüfung, ob alle Datensätze in NDX_KumUmsCust einen CustAccount zugeordnet haben
        NDXUmsatzClass::checkCustAccountRef();
    }

    // Besteht für alle Debitoren ein Referenz-Datensatz
    // Umsatz
    info(strfmt("@NDX:NDXReferenceCheckKumUmsCust", NDXHelperCommon::seconds2Str()));                   // [%1] Referenz-Prüfung, NDX_KumUmsCust
    while select        nDX_UmsCust
    group by        OrderAccount, CompanyId
    where           nDX_UmsCust.Month   == monat    &&
                    nDX_UmsCust.Jahr    == jahr
    notexists join  nDX_KumUmsCust
        where       nDX_KumUmsCust.CustAccount  == nDX_UmsCust.OrderAccount
            &&      nDX_KumUmsCust.CompanyId    == nDX_UmsCust.CompanyId
    {
        // Existiert eine Referenz über die Kundennummer (ansonsten ist es korrekt, das der Datensatz neue angelegt wird
        select firstOnly    l_nDX_KumUmsCust
        where           l_nDX_KumUmsCust.KdNr       == str2int(nDX_UmsCust.OrderAccount)
            &&          l_nDX_KumUmsCust.CompanyId  == nDX_UmsCust.CompanyId;
        if (l_nDX_KumUmsCust)
        {
            Warning(strfmt("@NDX:NDXCustomerWithoutRefKumUmsCust", l_nDX_KumUmsCust.KdNr));             // Debitor [%1] ohne CustAccount-Referenz in NDX_KumUmsCust
            ++nErrors;
        }
        else
        {
            info(strfmt("@NDX:NDXNewCustomerForSalesVolumeDisplay", nDX_UmsCust.OrderAccount));             // neuer Debitor für Umsatzdarstellung [%1]
        }

    }
    // Bonus
    info(strfmt("@NDX:NDXReferenceCheckKumBonCust", NDXHelperCommon::seconds2Str()));                   // [%1] Referenz-Prüfung, NDX_KumBonCust
    while select        nDX_UmsCust
    group by        OrderAccount, CompanyId
    where           nDX_UmsCust.Month   == monat    &&
                    nDX_UmsCust.Jahr    == jahr     &&
                    nDX_UmsCust.SofortbonusWert
    notexists join  nDX_KumBonCust
        where       nDX_KumBonCust.CustAccount  == nDX_UmsCust.OrderAccount
            &&      nDX_KumBonCust.CompanyId    == nDX_UmsCust.CompanyId
    {
        // Existiert eine Referenz über die Kundennummer (ansonsten ist es korrekt, das der Datensatz neue angelegt wird
        select firstOnly    l_nDX_KumBonCust
        where           l_nDX_KumBonCust.KdNr       == str2int(nDX_UmsCust.OrderAccount)
            &&          l_nDX_KumBonCust.CompanyId  == nDX_UmsCust.CompanyId;
        if (l_nDX_KumBonCust)
        {
            Warning(strfmt("@NDX:NDXCustomerWithoutRefKumBonCust", l_nDX_KumBonCust.KdNr));             // Debitor [%1] ohne CustAccount-Referenz in NDX_KumBonCust
            ++nErrors;
        }
        else
        {
            info(strfmt("@NDX:NDXNewCustomerForBonusDisplay", nDX_UmsCust.OrderAccount));             // neuer Debitor für Bonusdarstellung [%1]
        }

    }

    // Verbuchung nur, wenn keine Fehler festgestellt wurden
    if (nErrors)
    {
        throw Error(strfmt("@NDX:NDXUpdaateNotPerformedMissingReferences", nErrors));                           // Verbuchung wurde nicht durchgeführt, weil [%1] fehlende Referenzen festgestellt wurden
    }


    // Zunächst Umsätze des Monats initialisieren
    info(strfmt("@NDX:NDXSetSalesVolumeToZero", NDXHelperCommon::seconds2Str(), monat, jahr));      // [%1] Umsätze des Monats [%2-%3] auf 0 setzen
    {
        q       = new Query();
        qbds    = q.addDataSource(tablenum(NDXKumUmsCust));
        qbds.update(true);
        qbds.addRange(fieldnum(NDXKumUmsCust, jahr)).value(QueryValue(jahr));
        qr      = new QueryRun(q);
        ttsbegin;
        while (qr.next())
        {
            nDX_KumUmsCust  = qr.get(tablenum(NDXKumUmsCust));
            nDX_KumUmsCust.initUmsMonat(monat);
            nDX_KumUmsCust.update();
        }
        ttscommit;
        // Bonus zurücksetzen
        q       = new Query();
        qbds    = q.addDataSource(tablenum(NDXKumBonCust));
        qbds.update(true);
        qbds.addRange(fieldnum(NDXKumBonCust, year)).value(QueryValue(jahr));
        qr      = new QueryRun(q);
        ttsbegin;
        while (qr.next())
        {
            nDX_KumBonCust  = qr.get(tablenum(NDXKumBonCust));
            nDX_KumBonCust.initBonMonat(monat);
            nDX_KumBonCust.update();
        }
        ttscommit;
    }

    // Umsätze und Bonus zubuchen
    info(strfmt("@NDX:NDXPostSalesVolumeOfMonth", NDXHelperCommon::seconds2Str(), monat, jahr));      // [%1] Umsätze des Monats [%2-%3] zubuchen
    while select    nDX_UmsCustCompany
    group by    CompanyId
    where       nDX_UmsCustCompany.Month   == monat    &&
                nDX_UmsCustCompany.Jahr    == jahr
    {
        firma = NDXHelperCommon::CompanyId2NDXCompany(nDX_UmsCustCompany.CompanyId);
        changecompany(nDX_UmsCustCompany.CompanyId)
        {
            nDX_UmsCust = null;

            ttsbegin;
            while select    nDX_UmsCust
            where       nDX_UmsCust.CompanyId   == nDX_UmsCustCompany.CompanyId     &&
                        nDX_UmsCust.Month       == monat                            &&
                        nDX_UmsCust.Jahr        == jahr
            {
                // Umsatz
                nDX_KumUmsCust = null;
                nDX_KumUmsCust.CustAccount  = nDX_UmsCust.OrderAccount;
                nDX_KumUmsCust.CompanyId    = nDX_UmsCust.CompanyId;
                nDX_KumUmsCust.Jahr         = jahr;
                nDX_KumUmsCust.Party        = CustTable::find(nDX_KumUmsCust.CustAccount).Party;
                nDX_KumUmsCust              = NDXKumUmsCust::findOrCreate(nDX_KumUmsCust, true);
                nDX_KumUmsCust.Companys      = firma;
                if (!nDX_KumUmsCust.KdNr)
                {
                    nDX_KumUmsCust.KdNr = str2int(nDX_KumUmsCust.CustAccount);
                }

                nDX_KumUmsCust.addUmsFromNDXUmsCust(monat, nDX_UmsCust);
                nDX_KumUmsCust.update();


                // Bonus
                if (nDX_UmsCust.SofortbonusWert)
                {
                    nDX_KumBonCust = null;
                    nDX_KumBonCust.CustAccount  = nDX_UmsCust.OrderAccount;
                    nDX_KumBonCust.CompanyId    = nDX_UmsCust.CompanyId;
                    nDX_KumBonCust.Party        = CustTable::find(nDX_KumBonCust.CustAccount).Party;  // 1.3: NDX/PAFFH/NDX_TASK1235003633/20.02.2014
                    nDX_KumBonCust.Year         = jahr;
                    nDX_KumBonCust              = NDXKumBonCust::findOrCreate(nDX_KumBonCust, true);
                    nDX_KumBonCust.Company      = firma;
                    if (!nDX_KumBonCust.KdNr)
                    {
                        nDX_KumBonCust.KdNr = str2int(nDX_KumBonCust.CustAccount);
                    }

                    nDX_KumBonCust.addBonFromNDXUmsCust(monat, nDX_UmsCust);
                    nDX_KumBonCust.update();
                }
            }
            ttscommit;
        }
    }
    info(strfmt("@NDX:NDXSalesVolumeInKumUmsCustEnd", NDXHelperCommon::seconds2Str()));                   // [%1] ENDE: Umsätze in NDX_KumUmsCust aus Livedaten verbuchen
}

