}

/// <summary>
/// query builder alliance per item group
/// </summary>
/// <param name = "_umsatzQuery">query </param>
/// <param name = "_umsSignature">signatur</param>
/// <param name = "_alliance">alliance</param>
/// <returns>QueryRun</returns>
QueryRun buildQueryUmsAlliancePerArtGrp(NDXSalesVolumeQuery _umsatzQuery,
                                      NDXUmsSignature _umsSignature = this.parmUmsSignature(),
                                      CustAccount _alliance = this.parmlAlliance() ? this.parmMasterAlliance() : this.parmSalesGroupId())
{
    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds, qbds2;
    QueryBuildFieldList     fieldList;

    q = new Query();
    qbds = q.addDataSource(tablenum(NDXTmpKumUmsCustArtGrp));

    if (this.parmlAlliance())
    {
        qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, Alliance)).value(_alliance);
    }
    else
    {
        qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, SalesGroup)).value(_alliance);
    }

    qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, Child)).value(SysQuery::valueNot(_alliance));
    qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, UmsSignature)).value(_umsSignature);
    qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, MonthYearSignature)).value(this.parmMonthYearSignature());

    qbds2 = qbds.addDataSource(tablenum(NDXSNAllianceItemGroups));
    qbds2.relations(true);
    qbds2.joinMode(JoinMode::OuterJoin);
    qbds2.fetchMode(QueryFetchMode::One2One);

    switch (_umsatzQuery)
    {
        case NDXSalesVolumeQuery::perCompany:
        case NDXSalesVolumeQuery::allCompanies:
            qbds.orderMode(OrderMode::GroupBy);
            qbds.addSortField(fieldnum(NDXTmpKumUmsCustArtGrp, Company));
    }

    // Filterung
    switch (_umsatzQuery)
    {
        case NDXSalesVolumeQuery::perRecord       :
        case NDXSalesVolumeQuery::perCompany           :
            qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, Company)).value(SysQuery::valueNot(NDXCompanyBE::AllCompanies));
            break;
        case NDXSalesVolumeQuery::allCompanies        :
            qbds.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, Company)).value(SysQuery::value(NDXCompanyBE::AllCompanies));
            break;
    }

    // Sortierung
    switch (_umsatzQuery)
    {
        case NDXSalesVolumeQuery::perRecord:
            qbds.addSortField(fieldnum(NDXTmpKumUmsCustArtGrp, ItemGroup));
            break;
    }

    switch (_umsatzQuery)
    {
        case NDXSalesVolumeQuery::perCompany           :
        case NDXSalesVolumeQuery::allCompanies        :
            fieldList = qbds.fields();
            // Umsatz

            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, RecId), SelectionField::Count);

            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U01), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U02), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U03), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U04), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U05), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U06), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U07), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U08), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U09), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U10), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U11), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, U12), SelectionField::Sum);

            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU01), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU02), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU03), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU04), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU05), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU06), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU07), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU08), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU09), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU10), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU11), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCustArtGrp, VU12), SelectionField::Sum);

            break;
    }
    qr = new QueryRun(q);
    return qr;
}

/// <summary>
/// last modified: PaffH 17.03.25
/// </summary>
/// <param name = "_umsatzQuery">NDXSalesVolumeQuery</param>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_alliance">CustAccount</param>
/// <returns>QueryRun</returns>
QueryRun buildQueryUmsAlliancePerCustomer(NDXSalesVolumeQuery _umsatzQuery,
                                        NDXUmsSignature _umsSignature  = this.parmUmsSignature(),
                                        CustAccount     _alliance      = this.parmlAlliance() ? this.parmMasterAlliance() : this.parmSalesGroupId())
{
    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds, qbds2, qbds3;
    QueryBuildFieldList     fieldList;

    q       = new Query();
    qbds    = q.addDataSource(tablenum(NDXTmpKumUmsCust));
    if (this.parmlAlliance())
    {
        qbds.addRange(fieldnum(NDXTmpKumUmsCust, Alliance)).value(_alliance);
    }
    else
    {
        qbds.addRange(fieldnum(NDXTmpKumUmsCust, SalesGroup)).value(_alliance);
    }

    qbds.addRange(fieldnum(NDXTmpKumUmsCust, Child)).value(SysQuery::valueNot(_alliance));
    qbds.addRange(fieldnum(NDXTmpKumUmsCust, UmsSignature)).value(_umsSignature);
    qbds.addRange(fieldnum(NDXTmpKumUmsCust, MonthYearSignature)).value(this.parmMonthYearSignature());

    switch (_umsatzQuery)
    {
        case NDXSalesVolumeQuery::perRecord:
            qbds2 = qbds.addDataSource(tablenum(NDXAllianceTreeCustomer));
            qbds2.relations(true);
            qbds2.fetchMode(QueryFetchMode::One2One);
            qbds2.joinMode(JoinMode::OuterJoin);

            qbds3 = qbds.addDataSource(tablenum(NDXSNAllianceClients));
            qbds3.relations(true);
            qbds3.joinMode(JoinMode::OuterJoin);
            qbds3.fetchMode(QueryFetchMode::One2One);
            break;
        case NDXSalesVolumeQuery::SubAlliance:    // alle Unterverbände
            qbds2 = qbds.addDataSource(tablenum(NDXAllianceTreeCustomer));
            qbds2.addLink(fieldnum(NDXTmpKumUmsCust, Alliance), fieldnum(NDXAllianceTreeCustomer, Alliance));
            qbds2.addLink(fieldnum(NDXTmpKumUmsCust, Child), fieldnum(NDXAllianceTreeCustomer, AccountNum));
            qbds2.addLink(fieldnum(NDXTmpKumUmsCust, Company), fieldnum(NDXAllianceTreeCustomer, Company));
            qbds2.joinMode(JoinMode::InnerJoin);
            break;
    }

    switch (_umsatzQuery)
    {
        case NDXSalesVolumeQuery::subAlliance :
            qbds2.orderMode(OrderMode::GroupBy);
            qbds2.addSortField(fieldnum(NDXAllianceTreeCustomer, Child));
        case NDXSalesVolumeQuery::perCompany           :
            qbds.orderMode(OrderMode::GroupBy);
            qbds.addSortField(fieldnum(NDXTmpKumUmsCust, Company));
    }

    // Sortierung
    switch (_umsatzQuery)
    {
        case NDXSalesVolumeQuery::perRecord       :
            qbds.addSortField(fieldnum(NDXTmpKumUmsCust, Party));
            break;
    }

    switch (_umsatzQuery)
    {
        case NDXSalesVolumeQuery::SubAlliance :
        case NDXSalesVolumeQuery::perCompany :
        case NDXSalesVolumeQuery::allCompanies :
            fieldList = qbds.fields();
            // Umsatz

            fieldList.addField(fieldnum(NDXTmpKumUmsCust, RecId), SelectionField::Count);

            fieldList.addField(fieldnum(NDXTmpKumUmsCust, U01), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCust, U02), SelectionField::Sum);
            fieldList.addField(fieldnum(NDXTmpKumUmsCust, U03), SelectionField::Sum);
